(function () {
  'use strict';
  var FILES = [{"name":"demo/aflow.css","mime":"text/css","data":"/* =========================================================\n   AFlow · 算法解剖引擎样式\n   浅色主题，配色与主站令牌一致。三个案例包共用同一份。\n   ========================================================= */\n.af {\n  --af-ink: #242b2e; --af-ink2: #4d565b; --af-ink3: #79828a; --af-ink4: #9ba3a9;\n  --af-line: #e9e4d8; --af-line2: #f0ece1;\n  --af-jade: #2f7d6b; --af-jade-l: #e6f1ec; --af-jade-d: #22604f;\n  --af-clay: #b26a39; --af-red: #b05a51; --af-blue: #41699b;\n  border: 1px solid var(--af-line); border-radius: 12px; background: #fff;\n  padding: 14px 16px 12px; margin-top: 12px;\n}\n\n/* ---- 顶栏 ---- */\n.af-top { display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap; }\n.af-head { min-width: 0; }\n.af-ttl {\n  display: inline-block; font-size: 10px; font-weight: 700; letter-spacing: .1em;\n  color: var(--af-jade); font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  background: var(--af-jade-l); border-radius: 4px; padding: 2px 8px; margin-right: 8px;\n}\n.af-sub { font-size: 12.5px; color: var(--af-ink2); }\n.af-ctrls { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }\n.af-b {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  width: 28px; height: 26px; border-radius: 6px; cursor: pointer;\n  font-size: 12px; line-height: 1; font-family: inherit;\n  display: inline-flex; align-items: center; justify-content: center;\n  transition: all .14s;\n}\n.af-b:hover { border-color: var(--af-jade); color: var(--af-jade-d); background: var(--af-jade-l); }\n.af-play { width: 34px; font-size: 10px; }\n.af-sp {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  border-radius: 6px; height: 26px; font-size: 11px; font-family: inherit; padding: 0 4px; cursor: pointer;\n}\n.af-sp:focus { outline: 2px solid var(--af-jade); outline-offset: 1px; }\n\n/* ---- 阶段轨道 ---- */\n.af-rail {\n  display: flex; gap: 4px; margin-top: 11px; overflow-x: auto; padding-bottom: 2px;\n  scrollbar-width: thin;\n}\n.af-node {\n  flex: 1 1 0; min-width: 96px; text-align: left; cursor: pointer; font-family: inherit;\n  border: 1px solid var(--af-line); background: #fff; border-radius: 7px;\n  padding: 5px 8px 6px; display: block; transition: all .16s; position: relative;\n}\n.af-node:hover { border-color: var(--af-jade); }\n.af-node .af-n {\n  display: inline-block; font-size: 9px; font-weight: 700; color: var(--af-ink4);\n  font-family: ui-monospace, monospace; margin-right: 5px;\n}\n.af-node .af-nm { font-size: 11.5px; color: var(--af-ink2); font-weight: 600; }\n.af-node .af-tg {\n  display: block; font-size: 9px; color: var(--af-ink4); margin-top: 1px;\n  font-family: ui-monospace, monospace; letter-spacing: .01em;\n}\n.af-node.done { border-color: #cfe3da; background: #f7fbf9; }\n.af-node.done .af-n { color: var(--af-jade); }\n.af-node.on { border-color: var(--af-jade); background: var(--af-jade-l); box-shadow: 0 0 0 2px rgba(47,125,107,.1); }\n.af-node.on .af-n { color: var(--af-jade-d); }\n.af-node.on .af-nm { color: var(--af-jade-d); }\n.af-node.on .af-tg { color: var(--af-jade); }\n\n/* ---- 进度条 ---- */\n.af-prog { height: 3px; background: var(--af-line2); border-radius: 2px; margin-top: 8px; overflow: hidden; }\n.af-prog i { display: block; height: 100%; background: var(--af-jade); border-radius: 2px; transition: width .06s linear; }\n\n/* ---- 舞台 ---- */\n.af-stage { margin-top: 10px; }\n.af-stage svg {\n  display: block; width: 100%; height: auto; max-height: 620px;\n  background: #fbfaf6; border: 1px solid var(--af-line); border-radius: 9px;\n}\n\n/* ---- 说明 + 读数 ---- */\n.af-meta { display: grid; grid-template-columns: 1fr 250px; gap: 12px; margin-top: 10px; align-items: start; }\n.af-note {\n  font-size: 12.5px; line-height: 1.72; color: var(--af-ink2);\n  background: #f4f3ef; border-left: 3px solid var(--af-jade); border-radius: 0 5px 5px 0;\n  padding: 8px 12px; min-height: 38px;\n}\n.af-note b { color: var(--af-ink); font-weight: 700; }\n.af-note code, .af-note .mono {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 11.5px;\n  background: #fff; border: 1px solid var(--af-line); border-radius: 3px; padding: 0 4px;\n}\n.af-stats { display: flex; flex-wrap: wrap; gap: 5px; align-content: flex-start; }\n.af-stat {\n  background: #fff; border: 1px solid var(--af-line); border-radius: 6px;\n  padding: 4px 9px; min-width: 74px; flex: 1 1 auto;\n}\n.af-stat .k { display: block; font-size: 9.5px; color: var(--af-ink4); letter-spacing: .02em; }\n.af-stat .v {\n  display: block; font-family: ui-monospace, monospace; font-size: 13px;\n  font-weight: 600; color: var(--af-ink); margin-top: 1px;\n}\n.af-stat.t-ok .v { color: var(--af-jade-d); }\n.af-stat.t-warn .v { color: var(--af-clay); }\n.af-stat.t-bad .v { color: var(--af-red); }\n\n.af-count { margin-top: 7px; font-size: 10.5px; color: var(--af-ink4); font-family: ui-monospace, monospace; text-align: right; }\n\n@media (max-width: 860px) {\n  .af-meta { grid-template-columns: 1fr; }\n  .af-node { min-width: 84px; }\n  .af-node .af-nm { font-size: 11px; }\n}\n"},{"name":"demo/aflow.js","mime":"text/javascript","data":"/* =========================================================\n   AFlow · 算法解剖引擎（纯前端，零依赖）\n   ---------------------------------------------------------\n   用途：把「模型算法从输入走到输出」拆成若干可播放的阶段。\n   每个阶段跑的是真实的一段中间计算（不是抽象节点示意），\n   引擎负责：阶段轨道 / 播放控制 / 进度 / 实时读数 / 说明文字。\n\n   两种阶段写法\n   ------------\n   A) SVG 阶段 —— 适合示意图型中间量\n      { name, tag, dur,\n        draw: function (t, g, ctx) {\n          return { svg: '...', stats: [{k,v,tone}], note: '...' };\n        } }\n\n   B) DOM 阶段 —— 适合逐像素 / 逐节点的真实计算动画\n      { name, tag, dur,\n        init: function (host) {          // 只跑一次，构建 DOM\n          return {\n            update: function (t, ctx) {  // 每帧调用，负责重绘\n              return { stats: [...], note: '...' };\n            }\n          };\n        } }\n\n   用法：\n     AFlow.create({\n       mount: document.getElementById('flowMount'),\n       state: {},\n       stages: [ ... ]\n     });\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* ---------------- 配色（浅色主题，与主站令牌一致） ---------------- */\n  var C = {\n    ink: '#242b2e', ink2: '#4d565b', ink3: '#79828a', ink4: '#9ba3a9',\n    line: '#e9e4d8', line2: '#f0ece1', paper: '#fbfaf6', card: '#ffffff',\n    jade: '#2f7d6b', jadeL: '#e6f1ec', jadeD: '#22604f',\n    clay: '#b26a39', clayL: '#f8ecdf',\n    blue: '#41699b', blueL: '#e7eef9',\n    purple: '#7e5a8d', purpleL: '#efe9f4',\n    amber: '#c98a2b', amberL: '#faf3e2',\n    red: '#b05a51', redL: '#f9e9e5',\n    gray: '#79828a', grayL: '#f1f1ee'\n  };\n\n  /* 三栏坐标系：输入 → 算法内部 → 输出。画布 1000×520 */\n  var COLS = [\n    { x: 18, w: 272 },\n    { x: 312, w: 372 },\n    { x: 706, w: 276 }\n  ];\n  var TOP = 30, PANEL_H = 440, RAIL_Y = 484;\n\n  /* ---------------- 绘图 helper ---------------- */\n  var G = {\n    C: C, COLS: COLS, TOP: TOP, PANEL_H: PANEL_H,\n\n    esc: function (s) {\n      return String(s == null ? '' : s)\n        .replace(/&/g, '&amp;').replace(/<\/g, '&lt;').replace(/>/g, '&gt;');\n    },\n    f: function (v, n) {\n      n = (n === undefined) ? 2 : n;\n      if (v === null || v === undefined || !isFinite(v)) return '—';\n      return Number(v).toFixed(n);\n    },\n    rect: function (x, y, w, h, o) {\n      o = o || {};\n      return '<rect x=\"' + x + '\" y=\"' + y + '\" width=\"' + Math.max(0, w) + '\" height=\"' + Math.max(0, h) +\n        '\" rx=\"' + (o.r == null ? 4 : o.r) + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') + '/>';\n    },\n    line: function (x1, y1, x2, y2, o) {\n      o = o || {};\n      return '<line x1=\"' + x1 + '\" y1=\"' + y1 + '\" x2=\"' + x2 + '\" y2=\"' + y2 +\n        '\" stroke=\"' + (o.stroke || C.line) + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') + '/>';\n    },\n    path: function (d, o) {\n      o = o || {};\n      return '<path d=\"' + d + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.5 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') +\n        (o.join ? ' stroke-linejoin=\"' + o.join + '\"' : '') + '/>';\n    },\n    txt: function (x, y, s, o) {\n      o = o || {};\n      var size = o.size == null ? 11 : o.size;\n      var fill = o.fill || C.ink2;\n      var anchor = o.anchor || 'start';\n      var weight = o.weight ? ' font-weight=\"' + o.weight + '\"' : '';\n      var fam = o.mono ? ' font-family=\"ui-monospace,SFMono-Regular,Menlo,Consolas,monospace\"' : '';\n      var extra = (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.ls ? ' letter-spacing=\"' + o.ls + '\"' : '');\n      return '<text x=\"' + x + '\" y=\"' + y + '\" text-anchor=\"' + anchor + '\" font-size=\"' + size +\n        '\" fill=\"' + fill + '\"' + weight + fam + extra + '>' + G.esc(s) + '<\/text>';\n    },\n    circle: function (cx, cy, r, o) {\n      o = o || {};\n      return '<circle cx=\"' + cx + '\" cy=\"' + cy + '\" r=\"' + r + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.2 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') + '/>';\n    },\n    poly: function (pts, o) {\n      o = o || {};\n      var d = '';\n      for (var i = 0; i < pts.length; i++) d += (i ? 'L' : 'M') + pts[i][0].toFixed(1) + ' ' + pts[i][1].toFixed(1) + ' ';\n      return G.path(d + (o.close ? 'Z' : ''), o);\n    },\n    /* 标准三栏面板：全站统一的「输入 / 算法内部 / 输出」视觉语法 */\n    panel: function (ci, title, sub, color, dim) {\n      var c = COLS[ci];\n      var o = G.rect(c.x, TOP, c.w, PANEL_H, {\n        r: 8, fill: '#ffffff', stroke: dim ? '#efece1' : C.line, sw: 1\n      });\n      o += G.rect(c.x, TOP, c.w, 3, { r: 1.5, fill: color || C.line, op: dim ? 0.32 : 1 });\n      o += G.txt(c.x + 13, TOP + 25, title, { size: 12.5, fill: dim ? C.ink3 : C.ink, weight: 700 });\n      if (sub) o += G.txt(c.x + 13, TOP + 41, sub, { size: 10, fill: C.ink4 });\n      o += G.line(c.x, TOP + 50, c.x + c.w, TOP + 50, { stroke: C.line2 });\n      return o;\n    },\n    /* 栏间箭头：标出「数据流向下一层」 */\n    arrow: function (x, y, color, label, sub) {\n      var o = G.path('M' + x + ' ' + (y - 5) + 'L' + (x + 11) + ' ' + y + 'L' + x + ' ' + (y + 5) +\n        'L' + (x + 3) + ' ' + y + 'Z', { fill: color || C.line });\n      if (label) o += G.txt(x - 2, y - 11, label, { size: 9.5, fill: color || C.ink3, anchor: 'middle', weight: 700 });\n      if (sub) o += G.txt(x - 2, y + 18, sub, { size: 8.5, fill: C.ink4, anchor: 'middle' });\n      return o;\n    },\n    /* 数据形态缎带：把「输入张量 → 中间张量 → 输出张量」的形状串成一条 */\n    shapes: function (list, active) {\n      if (!list || !list.length) return '';\n      var o = '', x = 18, w = 964;\n      var n = list.length, pad = 7;\n      var cw = (w - pad * (n - 1)) / n;\n      for (var i = 0; i < n; i++) {\n        var on = (i === active);\n        o += G.rect(x, RAIL_Y, cw, 24, {\n          r: 5, fill: on ? C.jadeL : '#ffffff', stroke: on ? C.jade : C.line, sw: on ? 1.3 : 1\n        });\n        o += G.txt(x + cw / 2, RAIL_Y + 16, list[i], {\n          size: 9.5, anchor: 'middle', mono: true,\n          fill: on ? C.jadeD : C.ink3, weight: on ? 700 : 400\n        });\n        if (i < n - 1) o += G.txt(x + cw + pad / 2, RAIL_Y + 16, '→', { size: 10, fill: C.ink4, anchor: 'middle' });\n        x += cw + pad;\n      }\n      return o;\n    },\n    axes: function (x, y, w, h, o) {\n      o = o || {};\n      var s = G.rect(x, y, w, h, { r: 4, fill: o.fill || '#fdfdfb', stroke: o.stroke || C.line2 });\n      if (o.nx) for (var i = 1; i < o.nx; i++) {\n        s += G.line(x + w * i / o.nx, y, x + w * i / o.nx, y + h, { stroke: C.line2, op: 0.7 });\n      }\n      if (o.ny) for (var j = 1; j < o.ny; j++) {\n        s += G.line(x, y + h * j / o.ny, x + w, y + h * j / o.ny, { stroke: C.line2, op: 0.7 });\n      }\n      return s;\n    }\n  };\n\n  /* ---------------- 引擎 ---------------- */\n  function create(opts) {\n    var mount = opts.mount;\n    if (!mount) return null;\n    var stages = (opts.stages || []).filter(function (s) { return s && (typeof s.draw === 'function' || typeof s.init === 'function'); });\n    if (!stages.length) return null;\n\n    var state = opts.state || {};\n    var idx = 0, t = 0, playing = opts.autoplay !== false, speed = 1;\n    var raf = null, lastTs = 0, dirty = true;\n    var domStage = null, domHandle = null;\n\n    mount.innerHTML =\n      '<div class=\"af\">' +\n      '  <div class=\"af-top\">' +\n      '    <div class=\"af-head\">' +\n      '      <span class=\"af-ttl\">' + G.esc(opts.title || '算法解剖') + '<\/span>' +\n      '      <span class=\"af-sub\">' + G.esc(opts.subtitle || '自动播放：输入怎么一步步变成输出') + '<\/span>' +\n      '    <\/div>' +\n      '    <div class=\"af-ctrls\">' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"prev\" title=\"上一步\">‹<\/button>' +\n      '      <button type=\"button\" class=\"af-b af-play\" data-a=\"play\" title=\"播放/暂停\">❚❚<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"next\" title=\"下一步\">›<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"reset\" title=\"重播\">↺<\/button>' +\n      '      <select class=\"af-sp\" data-a=\"speed\" title=\"速度\">' +\n      '        <option value=\"0.5\">0.5×<\/option><option value=\"1\" selected>1×<\/option>' +\n      '        <option value=\"1.5\">1.5×<\/option><option value=\"2\">2×<\/option>' +\n      '      <\/select>' +\n      '    <\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-rail\"><\/div>' +\n      '  <div class=\"af-prog\"><i><\/i><\/div>' +\n      '  <div class=\"af-stage\"><\/div>' +\n      '  <div class=\"af-meta\">' +\n      '    <div class=\"af-note\"><\/div>' +\n      '    <div class=\"af-stats\"><\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-count\"><\/div>' +\n      '<\/div>';\n\n    var $ = function (sel) { return mount.querySelector(sel); };\n    var stageEl = $('.af-stage');\n    var railEl = $('.af-rail');\n    var progEl = $('.af-prog i');\n    var noteEl = $('.af-note');\n    var statsEl = $('.af-stats');\n    var countEl = $('.af-count');\n    var playBtn = $('[data-a=\"play\"]');\n\n    /* ---- 阶段轨道 ---- */\n    var nodeEls = stages.map(function (s, i) {\n      var b = document.createElement('button');\n      b.type = 'button';\n      b.className = 'af-node';\n      b.innerHTML = '<span class=\"af-n\">' + (i + 1) + '<\/span>' +\n        '<span class=\"af-nm\">' + G.esc(s.name) + '<\/span>' +\n        (s.tag ? '<span class=\"af-tg\">' + G.esc(s.tag) + '<\/span>' : '');\n      b.addEventListener('click', function () { goto(i); });\n      railEl.appendChild(b);\n      return b;\n    });\n\n    function goto(i) {\n      var ni = Math.max(0, Math.min(stages.length - 1, i));\n      if (ni !== idx) { disposeDom(); }\n      idx = ni; t = 0; dirty = true;\n      render(true);\n    }\n\n    /* 精确跳到某阶段的某个进度（0—1）。测试与「定位某一帧」用。 */\n    function seek(i, tt) {\n      goto(i);\n      t = Math.max(0, Math.min(1, tt == null ? 0 : tt));\n      dirty = true;\n      render(true);\n    }\n\n    function disposeDom() {\n      if (domHandle && typeof domHandle.destroy === 'function') {\n        try { domHandle.destroy(); } catch (e) { }\n      }\n      domHandle = null; domStage = null;\n    }\n\n    function totalDur() {\n      var s = 0;\n      for (var i = 0; i < stages.length; i++) s += (stages[i].dur || 2200);\n      return s;\n    }\n\n    function elapsed() {\n      var s = 0;\n      for (var i = 0; i < idx; i++) s += (stages[i].dur || 2200);\n      return s + t * (stages[idx].dur || 2200);\n    }\n\n    function render(force) {\n      if (!dirty && !force) return;\n      dirty = false;\n      var st = stages[idx];\n      var res = {};\n\n      try {\n        if (typeof st.init === 'function') {\n          /* DOM 阶段：init 只在进入该阶段时跑一次 */\n          if (domStage !== idx) {\n            disposeDom();\n            stageEl.innerHTML = '';\n            var host = document.createElement('div');\n            host.className = 'af-dom';\n            stageEl.appendChild(host);\n            domHandle = st.init(host) || {};\n            domStage = idx;\n          }\n          res = domHandle.update ? (domHandle.update(t, { index: idx, stage: st, state: state, api: api }) || {}) : {};\n        } else {\n          res = st.draw(t, G, { index: idx, stage: st, state: state, api: api }) || {};\n          stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\">' +\n            (res.svg || '') + '<\/svg>';\n        }\n      } catch (err) {\n        disposeDom();\n        stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\">' +\n          G.panel(1, '这一段出了点问题', String(err && err.message || err), C.red) +\n          G.txt(500, 260, '（算法计算中断，其余阶段不受影响）', { size: 11, fill: C.ink3, anchor: 'middle' }) +\n          '<\/svg>';\n        res = {\n          stats: [],\n          note: '<b style=\"color:' + C.red + '\">绘制失败：<\/b>' + G.esc(String(err && err.message || err))\n        };\n      }\n\n      /* 统计格 */\n      var stats = res.stats || [];\n      var h = '';\n      for (var i = 0; i < stats.length; i++) {\n        var s0 = stats[i];\n        h += '<div class=\"af-stat' + (s0.tone ? ' t-' + s0.tone : '') + '\">' +\n          '<span class=\"k\">' + G.esc(s0.k) + '<\/span><b class=\"v\">' + G.esc(s0.v) + '<\/b><\/div>';\n      }\n      statsEl.innerHTML = h;\n\n      noteEl.innerHTML = res.note || '';\n\n      for (var j = 0; j < nodeEls.length; j++) {\n        nodeEls[j].className = 'af-node' + (j === idx ? ' on' : (j < idx ? ' done' : ''));\n      }\n      countEl.textContent = '第 ' + (idx + 1) + ' / ' + stages.length + ' 步 · ' + (st.name || '');\n\n      progEl.style.width = (elapsed() / totalDur() * 100).toFixed(2) + '%';\n\n      playBtn.textContent = playing ? '❚❚' : '▶';\n      playBtn.title = playing ? '暂停' : '播放';\n    }\n\n    /* ---- 播放循环 ---- */\n    function tick(ts) {\n      raf = requestAnimationFrame(tick);\n      if (!lastTs) lastTs = ts;\n      var dt = Math.min(120, ts - lastTs);\n      lastTs = ts;\n      if (playing) {\n        var dur = stages[idx].dur || 2200;\n        t += (dt * speed) / dur;\n        if (t >= 1) {\n          if (idx < stages.length - 1) { disposeDom(); idx++; t = 0; }\n          else if (opts.loop !== false) { disposeDom(); idx = 0; t = 0; }\n          else { t = 1; playing = false; }\n        }\n        dirty = true;\n      }\n      if (dirty) render();\n    }\n\n    /* ---- 控制 ---- */\n    mount.querySelectorAll('.af-b, .af-sp').forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        var a = btn.getAttribute('data-a');\n        if (a === 'play') { playing = !playing; lastTs = 0; dirty = true; render(); }\n        else if (a === 'reset') { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); }\n        else if (a === 'prev') { if (t > 0.12) { t = 0; } else { goto(idx - 1); } dirty = true; render(); }\n        else if (a === 'next') { goto(idx + 1); }\n        else if (a === 'speed') { speed = parseFloat(btn.value) || 1; }\n      });\n    });\n    var sp = mount.querySelector('[data-a=\"speed\"]');\n    if (sp) sp.addEventListener('change', function () { speed = parseFloat(this.value) || 1; });\n\n    /* ---- 对外 API ---- */\n    var api = {\n      goto: goto,\n      seek: seek,\n      restart: function () { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); },\n      play: function () { playing = true; dirty = true; render(); },\n      pause: function () { playing = false; dirty = true; render(); },\n      refresh: function () { dirty = true; render(); },\n      get index() { return idx; },\n      setData: function (k, v) { state[k] = v; dirty = true; },\n      getData: function (k) { return state[k]; },\n      destroy: function () {\n        if (raf) cancelAnimationFrame(raf);\n        raf = null;\n        disposeDom();\n        mount.innerHTML = '';\n      }\n    };\n    if (opts.onReady) opts.onReady(api);\n\n    render(true);\n    raf = requestAnimationFrame(tick);\n    return api;\n  }\n\n  global.AFlow = { create: create, C: C, G: G, COLS: COLS };\n})(typeof window !== 'undefined' ? window : this);\n"},{"name":"demo/aiq.css","mime":"text/css","data":"/* =========================================================\n   AI 三问 · 可运行示范页通用区块\n   ---------------------------------------------------------\n   01 为什么（传统做法 vs AI 做法的同一段数据对照）\n   02 是什么（把业务对象翻译成算法可处理的形式）\n   03 怎样实现（五步工程路线，可跳到下方逐帧解剖）\n   依赖各包 demo.css 里的 --jade / --clay / --blue / --ink*\n   ========================================================= */\n\n.aiq {\n  margin: 0 0 18px; padding: 15px 18px 16px;\n  background: linear-gradient(180deg, #fbfaf6 0%, #ffffff 52%);\n  border: 1px solid var(--line, #e9e4d8); border-radius: 12px;\n}\n.aiq-top { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 12px; }\n.aiq-chip {\n  flex: none; font-size: 10px; font-weight: 700; letter-spacing: .12em;\n  color: var(--jade, #2f7d6b); background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  border-radius: 999px; padding: 3px 9px; margin-top: 1px;\n}\n.aiq-lede { margin: 0; font-size: 13px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-lede b { color: var(--ink, #242b2e); }\n\n.aiq-grid { display: grid; grid-template-columns: 1.32fr 1fr 1fr; gap: 11px; }\n@media (max-width: 1040px) and (min-width: 760px) {\n  .aiq-grid { grid-template-columns: 1fr 1fr; grid-template-areas: \"a a\" \"b c\"; }\n  .aiq-card.q1 { grid-area: a; }\n  .aiq-card.q2 { grid-area: b; }\n  .aiq-card.q3 { grid-area: c; }\n}\n@media (max-width: 759px) { .aiq-grid { grid-template-columns: 1fr; } }\n.aiq-foot { margin: auto 0 0; padding-top: 2px; font-size: 10.5px; line-height: 1.5; color: var(--ink-4, #9ba3a9); }\n\n.aiq-card {\n  display: flex; flex-direction: column; gap: 9px;\n  border: 1px solid var(--line, #e9e4d8); border-radius: 10px;\n  background: #fff; padding: 11px 12px 11px;\n}\n.aiq-hd {\n  display: flex; align-items: center; gap: 7px;\n  padding-bottom: 8px; border-bottom: 1px dashed var(--line, #e9e4d8);\n}\n.aiq-hd .n {\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 10.5px; font-weight: 700; color: #fff;\n  border-radius: 5px; padding: 2px 6px; line-height: 1.5;\n}\n.aiq-hd > div { display: flex; align-items: baseline; gap: 4px; }\n.aiq-hd b { font-size: 14px; color: var(--ink, #242b2e); letter-spacing: .01em; }\n.aiq-hd em {\n  font-style: normal; font-size: 9px; letter-spacing: .16em; color: var(--ink-4, #9ba3a9);\n}\n.aiq-card.q1 .aiq-hd .n { background: var(--clay, #b26a39); }\n.aiq-card.q2 .aiq-hd .n { background: var(--blue, #41699b); }\n.aiq-card.q3 .aiq-hd .n { background: var(--jade, #2f7d6b); }\n\n/* ---------- 01 为什么：曲线对照 ---------- */\n.aiq-switch {\n  display: inline-flex; align-self: flex-start; gap: 2px; padding: 2px;\n  background: var(--card, #fbfaf6); border: 1px solid var(--line, #e9e4d8); border-radius: 999px;\n}\n.aiq-switch button {\n  font: inherit; font-size: 11.5px; line-height: 1.5; cursor: pointer;\n  border: 0; background: transparent; color: var(--ink-3, #79828a);\n  padding: 3px 11px; border-radius: 999px; transition: all .15s;\n}\n.aiq-switch button:hover { color: var(--ink, #242b2e); }\n.aiq-switch button.on {\n  background: #fff; color: var(--ink, #242b2e); font-weight: 600;\n  box-shadow: 0 1px 3px rgba(0, 0, 0, .08);\n}\n.aiq-fig { margin: 1px 0 0; }\n.aiq-fig svg { display: block; width: 100%; height: auto; }\n\n.aiq-nums {\n  display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px;\n  margin: 0; padding: 0; list-style: none;\n}\n.aiq-nums li {\n  background: var(--card, #fbfaf6); border: 1px solid #efeadf; border-radius: 7px;\n  padding: 5px 6px 6px; text-align: center;\n}\n.aiq-nums b {\n  display: block; font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 14.5px; line-height: 1.25; color: var(--ink-2, #4d565b);\n  font-variant-numeric: tabular-nums; transition: color .2s;\n}\n.aiq-nums span { display: block; font-size: 10px; color: var(--ink-3, #79828a); line-height: 1.35; margin-top: 2px; }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"good\"] b { color: var(--jade, #2f7d6b); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"bad\"] b { color: var(--clay, #b26a39); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"neut\"] b { color: var(--ink, #242b2e); }\n\n.aiq-note { margin: 0; font-size: 11.5px; line-height: 1.62; color: var(--ink-3, #79828a); }\n.aiq-note b { color: var(--ink-2, #4d565b); }\n.aiq-note .hl-bad { color: var(--clay, #b26a39); font-weight: 600; }\n.aiq-note .hl-good { color: var(--jade, #2f7d6b); font-weight: 600; }\n\n/* ---------- 02 是什么：翻译管线 + 式子 ---------- */\n.aiq-say { margin: 0; font-size: 12.5px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-say b { color: var(--ink, #242b2e); }\n.aiq-pipe { display: flex; flex-direction: column; }\n.aiq-pipe .p {\n  position: relative; padding: 5px 8px 5px 27px; border-radius: 6px;\n  background: var(--card, #fbfaf6); font-size: 11.5px; line-height: 1.5; color: var(--ink-3, #79828a);\n}\n.aiq-pipe .p i {\n  position: absolute; left: 8px; top: 6px; font-style: normal;\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px;\n  color: var(--blue, #41699b); font-weight: 700; letter-spacing: .02em;\n}\n.aiq-pipe .p b { color: var(--ink-2, #4d565b); font-weight: 600; }\n.aiq-pipe .ar { display: grid; place-items: center; height: 11px; }\n.aiq-pipe .ar::before {\n  content: \"\"; width: 1px; height: 7px; background: #ddd6c8;\n  box-shadow: 0 7px 0 -2px #ddd6c8;\n}\n.aiq-eq {\n  margin: 0; padding: 6px 9px; border-radius: 7px;\n  background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 11px; line-height: 1.8; color: #1f5f4d;\n  overflow-x: auto; white-space: nowrap;\n}\n.aiq-eq em { font-style: normal; color: #5f8f80; font-size: 10px; }\n.aiq-fit { margin: 0; padding: 0; list-style: none; font-size: 11.5px; line-height: 1.56; color: var(--ink-2, #4d565b); }\n.aiq-fit li { position: relative; padding-left: 15px; }\n.aiq-fit li + li { margin-top: 2px; }\n.aiq-fit li i { position: absolute; left: 0; top: 0; font-style: normal; font-weight: 700; }\n.aiq-fit .y i { color: var(--jade, #2f7d6b); }\n.aiq-fit .n i { color: var(--clay, #b26a39); }\n\n/* ---------- 03 怎样实现：五步 + 跳转 ---------- */\n.aiq-steps { margin: 0; padding: 0; list-style: none; counter-reset: aiqs; }\n.aiq-steps li {\n  position: relative; padding-left: 20px;\n  font-size: 11.5px; line-height: 1.55; color: var(--ink-2, #4d565b);\n}\n.aiq-steps li + li { margin-top: 5px; }\n.aiq-steps li::before {\n  counter-increment: aiqs; content: counter(aiqs);\n  position: absolute; left: 0; top: 1px; width: 14px; height: 14px;\n  border-radius: 50%; background: var(--jade-bg, #e6f1ec); color: var(--jade, #2f7d6b);\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px; font-weight: 700;\n  display: grid; place-items: center;\n}\n.aiq-steps li b { color: var(--ink, #242b2e); font-weight: 600; }\n.aiq-steps li code {\n  font-family: ui-monospace, Consolas, monospace; font-size: 10px;\n  background: #f3f0e8; border-radius: 3px; padding: 0 3px; color: #5c666b;\n}\n.aiq-jump {\n  margin-top: auto; padding-top: 8px; border-top: 1px dashed var(--line, #e9e4d8);\n  display: flex; align-items: center; justify-content: space-between; gap: 8px;\n}\n.aiq-jump span { font-size: 11px; color: var(--ink-4, #9ba3a9); }\n.aiq-jump a {\n  font-size: 11.5px; font-weight: 600; color: var(--jade, #2f7d6b);\n  text-decoration: none; white-space: nowrap;\n}\n.aiq-jump a:hover { color: #1f5f4d; text-decoration: underline; }\n\n/* 折叠态的三问（窄屏或用户收起时） */\n@media (max-width: 720px) {\n  .aiq { padding: 13px 12px 14px; }\n  .aiq-top { flex-direction: column; gap: 6px; }\n  .aiq-nums b { font-size: 13.5px; }\n}\n\n/* ---------- 03 卡内的踩坑提示 ---------- */\n.aiq-warn {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: var(--clay-bg, #f7ece2); border: 1px solid #eed9c6;\n  font-size: 11.5px; line-height: 1.6; color: #8a4f28;\n}\n.aiq-warn b { display: block; font-size: 10px; letter-spacing: .06em; color: var(--clay, #b26a39); margin-bottom: 2px; }\n\n/* ---------- 01 卡的对比表（没有可画的数字时用） ---------- */\n.aiq-tbl { width: 100%; border-collapse: collapse; font-size: 11.5px; }\n.aiq-tbl th {\n  font-size: 9.5px; font-weight: 600; color: var(--ink-4, #9ba3a9);\n  text-align: left; padding: 0 6px 5px; border-bottom: 1px solid var(--line, #e9e4d8);\n  letter-spacing: .02em;\n}\n.aiq-tbl th:first-child { padding-left: 0; }\n.aiq-tbl th:nth-child(2) { color: #8a9099; }\n.aiq-tbl th:nth-child(3) { color: var(--jade, #2f7d6b); }\n.aiq-tbl td {\n  padding: 5px 6px; border-bottom: 1px dashed #f2eee4;\n  color: var(--ink-2, #4d565b); line-height: 1.45; vertical-align: top;\n}\n.aiq-tbl td:first-child { padding-left: 0; color: var(--ink-3, #79828a); font-size: 11px; white-space: nowrap; }\n.aiq-tbl td:nth-child(2) { color: #7b838a; }\n.aiq-tbl td:nth-child(3) { color: #1f5f4d; font-weight: 500; }\n.aiq-tbl tr:last-child td { border-bottom: 0; }\n\n/* ---------- 01 卡的「代价」补充（填满短卡，也把边界说清） ---------- */\n.aiq-cost {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: #f4f2ea; border: 1px solid #e8e3d5;\n  font-size: 11.5px; line-height: 1.6; color: #5f676c;\n}\n.aiq-cost b { display: block; font-size: 10px; letter-spacing: .06em; color: #8a9099; margin-bottom: 2px; }\n"},{"name":"demo/aiq.js","mime":"text/javascript","data":"/* =========================================================\n   AI 三问 · 交互（只服务 01「为什么」卡的曲线对照）\n   ---------------------------------------------------------\n   同一段数据、同一条劣化曲线，切换「传统做法 / AI 做法」：\n   传统只在越过阈值那一刻报警；AI 在曲线还落在正常区间时就\n   从「偏离自身基线」的趋势里看出苗头。图上同时给出两处标记、\n   提前量与三个指标数字。\n   无依赖，data-* 配置，多实例安全。\n   ========================================================= */\n(function () {\n  'use strict';\n  var NS = 'http://www.w3.org/2000/svg';\n\n  function mk(name, attrs) {\n    var e = document.createElementNS(NS, name);\n    for (var k in attrs) if (attrs.hasOwnProperty(k)) e.setAttribute(k, attrs[k]);\n    return e;\n  }\n  function txt(s, x, y, o) {\n    var t = mk('text', {\n      x: x, y: y,\n      'font-size': (o && o.size) || 9.5,\n      fill: (o && o.fill) || '#79828a',\n      'text-anchor': (o && o.anchor) || 'start',\n      'font-family': 'ui-monospace, \"SF Mono\", Consolas, monospace',\n      'font-weight': (o && o.weight) || 400\n    });\n    t.textContent = s;\n    return t;\n  }\n\n  /* 曲线：t∈[0,100] → 归一化高度 v∈[0,1]（1=顶部） */\n  function valAt(t, shape, onset) {\n    var a;\n    if (t <= onset) a = 0.295 + 0.095 * (t / Math.max(1, onset));\n    else a = 0.39 + 0.55 * Math.pow((t - onset) / (100 - onset), 1.55);\n    return shape === 'fall' ? 1 - a : a;\n  }\n\n  var W = 420, H = 150, L = 30, R = 10, T = 12, B = 32;\n  function xOf(t) { return L + t / 100 * (W - L - R); }\n  function yOf(v) { return (H - B) - v * ((H - B) - T); }\n\n  /* 条形对比：同一批井/同一批任务，旧做法与新做法的指标代差 */\n  function drawBar(box, mode, cfg) {\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var rows = cfg.rows;\n    var W2 = 372, H2 = 150, TOP = 14, RH = 40, LAB = 92, BARX = 92, BARW = 186;\n    var svg = mk('svg', { viewBox: '0 0 ' + W2 + ' ' + H2, role: 'img' });\n    svg.setAttribute('aria-label', '旧做法与新做法的指标对比');\n\n    var i, r, oldOn = mode === 'old';\n    for (i = 0; i < rows.length; i++) {\n      r = rows[i];\n      var y = TOP + i * RH;\n      svg.appendChild(txt(r[0], 2, y + 11, { size: 10, fill: '#4d565b' }));\n      if (r[4]) svg.appendChild(txt(r[4], 2, y + 24, { size: 8.5, fill: '#9ba3a9' }));\n\n      /* 行首两枚色条：旧 / 新 */\n      svg.appendChild(mk('rect', { x: 0, y: y + 5, width: 2, height: 9, fill: '#8a9099', opacity: oldOn ? 0.9 : 0.25 }));\n      svg.appendChild(mk('rect', { x: 0, y: y + 20, width: 2, height: 9, fill: '#2f7d6b', opacity: oldOn ? 0.25 : 0.9 }));\n\n      /* 纯文本行（无数字可画条） */\n      if (!r[5]) {\n        svg.appendChild(txt(r[1], BARX, y + 12, { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 600 : 400 }));\n        svg.appendChild(txt(r[2], BARX, y + 27, { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 600 }));\n        continue;\n      }\n\n      /* 每行按自身量级归一：不同指标量纲不同，跨行比较没有意义 */\n      var rmax = Math.max(r[1], r[2]) || 1;\n      var wOld = Math.max(2, r[1] / rmax * BARW), wNew = Math.max(2, r[2] / rmax * BARW);\n      var unit = r[3] === '%' ? '%' : (r[3] ? ' ' + r[3] : '');\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 4, width: wOld, height: 9, rx: 2, fill: '#8a9099', opacity: oldOn ? 0.85 : 0.22 }));\n      svg.appendChild(txt(fmt(r[1]) + unit, BARX + BARW + 8, y + 12,\n        { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 700 : 400 }));\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 19, width: wNew, height: 9, rx: 2, fill: '#2f7d6b', opacity: oldOn ? 0.22 : 0.88 }));\n      svg.appendChild(txt(fmt(r[2]) + unit, BARX + BARW + 8, y + 27,\n        { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 700 }));\n    }\n\n    /* 图例 */\n    svg.appendChild(mk('rect', { x: BARX, y: H2 - 9, width: 8, height: 3, fill: '#8a9099', opacity: 0.85 }));\n    svg.appendChild(txt('旧做法', BARX + 12, H2 - 4, { size: 8.5, fill: '#79828a' }));\n    svg.appendChild(mk('rect', { x: BARX + 52, y: H2 - 9, width: 8, height: 3, fill: '#2f7d6b', opacity: 0.88 }));\n    svg.appendChild(txt('新做法', BARX + 64, H2 - 4, { size: 8.5, fill: '#79828a' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n  function fmt(v) {\n    var n = Number(v);\n    if (!isFinite(n)) return String(v);\n    return Math.abs(n) >= 100 ? n.toFixed(0) : (Math.abs(n) >= 10 ? n.toFixed(n % 1 ? 1 : 0) : n.toFixed(n % 1 ? 1 : 0));\n  }\n\n  function draw(box, mode, cfg) {\n    if (cfg.kind === 'bar') { drawBar(box, mode, cfg); return; }\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var svg = mk('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img' });\n    svg.setAttribute('aria-label', '传统做法与 AI 做法的检出时机对比');\n\n    /* 网格 */\n    for (var g = 1; g <= 3; g++) {\n      svg.appendChild(mk('line', {\n        x1: L, y1: yOf(0.24 * g), x2: W - R, y2: yOf(0.24 * g),\n        stroke: '#f1ede2', 'stroke-width': 1\n      }));\n    }\n\n    /* 正常区间带 */\n    var lo = cfg.bandLo, hi = cfg.bandHi;\n    svg.appendChild(mk('rect', {\n      x: L, y: yOf(hi), width: W - L - R, height: Math.max(2, yOf(lo) - yOf(hi)),\n      fill: '#2f7d6b', opacity: 0.07\n    }));\n    svg.appendChild(txt('正常区间', W - R - 3, yOf(hi) + 9, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    /* 报警阈值 */\n    svg.appendChild(mk('line', {\n      x1: L, y1: yOf(cfg.thr), x2: W - R, y2: yOf(cfg.thr),\n      stroke: '#b26a39', 'stroke-width': 1.1, 'stroke-dasharray': '4 3', opacity: 0.6\n    }));\n    svg.appendChild(txt('阈值 θ', W - R - 3, yOf(cfg.thr) - 4, { anchor: 'end', size: 8.5, fill: '#b26a39' }));\n\n    /* 曲线 */\n    var d = '', i, v;\n    for (i = 0; i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      d += (i ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: d, fill: 'none', stroke: '#4d565b', 'stroke-width': 1.7,\n      'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 劣化起点 */\n    svg.appendChild(mk('line', {\n      x1: xOf(cfg.onset), y1: yOf(cfg.thr) - 2, x2: xOf(cfg.onset), y2: yOf(0.06),\n      stroke: '#cfc9bb', 'stroke-width': 1, 'stroke-dasharray': '2 3'\n    }));\n\n    /* 从判定点起，曲线高亮 */\n    var from = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var dd = '';\n    for (i = Math.round(from); i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      dd += (dd ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: dd, fill: 'none',\n      stroke: mode === 'new' ? '#2f7d6b' : '#b26a39',\n      'stroke-width': 2.6, 'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 底部时间轴上的「提前量」量尺 */\n    var yB = H - 15;\n    if (mode === 'new' && cfg.newAt < cfg.oldAt) {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.newAt), y1: yB, x2: xOf(cfg.oldAt), y2: yB,\n        stroke: '#2f7d6b', 'stroke-width': 2.4, opacity: 0.3, 'stroke-linecap': 'round'\n      }));\n      [cfg.newAt, cfg.oldAt].forEach(function (t) {\n        svg.appendChild(mk('line', {\n          x1: xOf(t), y1: yB - 3.5, x2: xOf(t), y2: yB + 3.5,\n          stroke: '#2f7d6b', 'stroke-width': 1.2\n        }));\n      });\n      svg.appendChild(txt('提前 ' + cfg.days + ' 天', (xOf(cfg.newAt) + xOf(cfg.oldAt)) / 2, yB - 5,\n        { anchor: 'middle', size: 9, fill: '#2f7d6b', weight: 600 }));\n    } else {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.oldAt), y1: yB, x2: W - R, y2: yB,\n        stroke: '#b26a39', 'stroke-width': 2.4, opacity: 0.28, 'stroke-linecap': 'round'\n      }));\n      svg.appendChild(txt('这段没有任何预警', W - R - 3, yB - 5,\n        { anchor: 'end', size: 9, fill: '#b26a39', weight: 600 }));\n    }\n\n    /* 判定点 */\n    var tx = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var px = xOf(tx), py = yOf(valAt(tx, cfg.shape, cfg.onset));\n    var col = mode === 'new' ? '#2f7d6b' : '#b26a39';\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 6.5, fill: col, opacity: 0.15 }));\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 3.2, fill: col, stroke: '#fff', 'stroke-width': 1.3 }));\n\n    /* 标签固定在左上角，用细引线指到判定点：两种模式切换时位置不跳，便于对比 */\n    var label = mode === 'new' ? '这里就预警' : '越限才发现';\n    var tw = label.length * 9 + 11, th = 15;\n    var tX = L + 3, tY = T + 1;\n    svg.appendChild(mk('line', {\n      x1: tX + tw / 2, y1: tY + th, x2: px, y2: py - 5,\n      stroke: col, 'stroke-width': 0.8, 'stroke-dasharray': '2 3', opacity: 0.45\n    }));\n    svg.appendChild(mk('rect', {\n      x: tX, y: tY, width: tw, height: th, rx: 3.5,\n      fill: '#fffdf7', stroke: col, 'stroke-width': 0.8, 'stroke-opacity': 0.4\n    }));\n    svg.appendChild(txt(label, tX + 6, tY + 11, { size: 9, fill: col, weight: 600 }));\n\n    /* 轴与单位 */\n    svg.appendChild(txt('时间 →', L, H - 3, { size: 8.5, fill: '#9ba3a9' }));\n    svg.appendChild(txt(cfg.unit, W - R, T + 2, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n\n  function init(box) {\n    var cfg = {\n      shape: box.getAttribute('data-shape') || 'rise',\n      unit: box.getAttribute('data-unit') || '',\n      onset: parseFloat(box.getAttribute('data-onset')) || 55,\n      thr: parseFloat(box.getAttribute('data-thr')) || 0.72,\n      oldAt: parseFloat(box.getAttribute('data-old-at')) || 88,\n      newAt: parseFloat(box.getAttribute('data-new-at')) || 60,\n      days: box.getAttribute('data-days') || '',\n      kind: box.getAttribute('data-kind') || 'trend',\n      rows: (box.getAttribute('data-rows') || '').split(';').filter(function (x) { return x.trim(); }).map(function (x) {\n        var p = x.split('|');\n        var num = isFinite(parseFloat(p[1])) && isFinite(parseFloat(p[2]));\n        return [p[0] || '', num ? parseFloat(p[1]) : (p[1] || ''), num ? parseFloat(p[2]) : (p[2] || ''), p[3] || '', p[4] || '', num];\n      }),\n      bandLo: parseFloat(box.getAttribute('data-band-lo')) || 0.26,\n      bandHi: parseFloat(box.getAttribute('data-band-hi')) || 0.46\n    };\n    var btns = box.querySelectorAll('.aiq-switch button');\n    var nums = box.querySelectorAll('.aiq-nums b[data-old]');\n    var notes = box.querySelectorAll('.aiq-note [data-v]');\n\n    function set(mode) {\n      box.setAttribute('data-mode', mode);\n      [].forEach.call(btns, function (b) { b.classList.toggle('on', b.getAttribute('data-v') === mode); });\n      [].forEach.call(nums, function (n) {\n        var v = n.getAttribute('data-' + (mode === 'old' ? 'old' : 'new'));\n        if (v != null && v !== '') n.textContent = v;\n      });\n      [].forEach.call(notes, function (n) { n.hidden = n.getAttribute('data-v') !== mode; });\n      draw(box, mode, cfg);\n    }\n\n    if (!btns.length) { set('new'); return; }\n    [].forEach.call(btns, function (b) {\n      b.addEventListener('click', function () { set(b.getAttribute('data-v')); });\n    });\n    set('old');\n  }\n\n  function boot() {\n    [].forEach.call(document.querySelectorAll('[data-aiq]'), init);\n  }\n  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);\n  else boot();\n})();\n"},{"name":"demo/demo.css","mime":"text/css","data":"/* =========================================================\n   地质剖面遥感解译 · 示范页样式（整页模式，沙箱 iframe）\n   浅色主题：全部使用设计令牌 / 低饱和浅色 hex\n   ========================================================= */\n:root {\n  --jade: #2f7d6b;\n  --jade-bg: #e6f1ec;\n  --clay: #b26a39;\n  --clay-bg: #f7ece2;\n  --blue: #41699b;\n  --blue-bg: #e7eef9;\n  --ink: #242b2e;\n  --ink-2: #4d565b;\n  --ink-3: #79828a;\n  --ink-4: #9ba3a9;\n  --line: #e9e4d8;\n  --card: #fbfaf6;\n  --bg: #faf9f4;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  padding: 20px 22px 26px;\n  background: var(--bg);\n  color: var(--ink);\n  font: 14.5px/1.7 -apple-system, \"Segoe UI\", \"Microsoft YaHei\", system-ui, sans-serif;\n}\n\n/* ---------- 头部 ---------- */\n.hd { margin-bottom: 18px; }\n.kicker { font-size: 10.5px; letter-spacing: .14em; color: var(--jade); font-weight: 700; }\n.hd h1 { margin: 4px 0 6px; font-size: 21px; color: var(--ink); }\n.hd .sub { margin: 0; color: var(--ink-3); font-size: 13.5px; }\n\n/* ---------- 区块 ---------- */\n.sec {\n  margin-bottom: 26px; padding: 18px 20px;\n  background: var(--card); border: 1px solid var(--line); border-radius: 12px;\n}\n.sec-hd { margin-bottom: 12px; }\n.sec-no { font-size: 10.5px; letter-spacing: .12em; color: var(--ink-4); font-weight: 700; text-transform: uppercase; }\n.sec-hd h2 { margin: 3px 0 6px; font-size: 17px; color: var(--ink); }\n.sec-hd .leadline { margin: 0; color: var(--ink-3); font-size: 13px; }\n.sec-hd .leadline b { color: var(--ink); }\n\n/* ---------- 图例 ---------- */\n.legend { display: flex; flex-wrap: wrap; gap: 8px 14px; margin: 8px 0 4px; }\n.legend .lg { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; color: var(--ink-2); }\n.legend .lg i { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }\n\n/* ---------- 控件 ---------- */\n.ctl { display: flex; flex-wrap: wrap; gap: 14px 24px; align-items: center; margin-bottom: 12px; padding: 10px 12px; background: var(--bg); border: 1px solid var(--line); border-radius: 10px; }\n.ctl .btns { display: flex; flex-wrap: wrap; gap: 6px; }\n.ctl .btns button { font: inherit; font-size: 12.5px; padding: 5px 12px; border-radius: 8px; border: 1px solid var(--line); background: #fff; color: var(--ink-2); cursor: pointer; }\n.ctl .btns button.on, .ctl .btns button:hover { background: var(--jade); color: #fff; border-color: var(--jade); }\n.ctl .sl { display: flex; flex-direction: column; gap: 3px; min-width: 180px; }\n.ctl .sl label { font-size: 12.5px; color: var(--ink-2); display: flex; justify-content: space-between; align-items: center; }\n.ctl .sl output { font-family: ui-monospace, monospace; font-size: 13px; color: var(--jade); font-weight: 600; }\n.ctl input[type=range] { width: 100%; accent-color: var(--jade); }\n\n/* ---------- SVG 图 ---------- */\n.chart-wrap { width: 100%; }\n.chart-wrap svg { width: 100%; height: auto; display: block; border: 1px solid var(--line); border-radius: 8px; background: #fff; }\n.fg { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.fg .cap { font-size: 12px; color: var(--ink-3); text-align: center; margin-top: 6px; }\n@media (max-width:720px){ .fg { grid-template-columns: 1fr; } }\n\n/* ---------- 结果读数行 ---------- */\n.rrow { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 12px; }\n.ro { flex: 1; min-width: 130px; background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }\n.ro .k { display: block; font-size: 11px; color: var(--ink-4); margin-bottom: 2px; }\n.ro b { font-size: 15px; color: var(--ink); }\n.ro b.good { color: var(--jade); }\n.ro b.warn { color: var(--clay); }\n\n/* ---------- 提示 / 折叠 ---------- */\n.tip { margin: 10px 0 0; font-size: 12.5px; color: var(--ink-3); background: var(--jade-bg); border-radius: 8px; padding: 8px 12px; }\n.details { margin-top: 12px; }\n.details summary { cursor: pointer; font-size: 13px; color: var(--jade); font-weight: 600; }\n\n/* 算法解剖引擎在 aflow.css 里；AI 三问在 aiq.css 里 */\n"},{"name":"demo/demo.js","mime":"text/javascript","data":"/* =========================================================\n   露头裂缝自动统计 · 示范页脚本\n   ---------------------------------------------------------\n   用合成的「露头裂缝照片」演示三条智能化主线：\n     实验 1 · 裂缝实例分割：每条裂缝一个掩膜\n     实验 2 · 骨架化 + 线密度：中心线、长度、密度\n     实验 3 · 产状反算 + 验证：走向玫瑰图 + 实测校准\n\n   文件内部分层：\n     1) Model（纯模型层，Node 可 require，供 flow.js 复用）\n     2) 浏览器接线（$ 工具 + 三屏渲染 + Bridge 桥接 + 抽屉上报）\n   ========================================================= */\n(function (root, factory) {\n  if (typeof module === 'object' && module.exports) module.exports = factory();\n  else root.Model = factory();\n})(typeof window !== 'undefined' ? window : this, function () {\n  'use strict';\n\n  var M = {};\n\n  /* ---------- 固定种子随机数（mulberry32） ---------- */\n  function mulberry32(seed) {\n    var a = seed >>> 0;\n    return function () {\n      a |= 0; a = (a + 0x6D2B79F5) | 0;\n      var t = Math.imul(a ^ (a >>> 15), 1 | a);\n      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\n      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n    };\n  }\n  M.mulberry32 = mulberry32;\n\n  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\n\n  /* =========================================================\n     合成露头裂缝照片\n     ---------------------------------------------------------\n     W×H 栅格，岩面背景（不同色调）+ 裂缝（细长低对比线段）。\n     每条裂缝有真实走向（angle）、长度、像素坐标，作真值。\n     ========================================================= */\n  function genOutcrop(seed, W, H) {\n    W = W || 64; H = H || 48;\n    var rng = mulberry32(seed || 20261105);\n    var bg = new Uint8Array(W * H);        /* 背景色调 */\n    var px = new Uint8Array(W * H);        /* 0=岩面 1=裂缝 */\n    var conf = new Float32Array(W * H);\n\n    /* 岩面背景：两三种色调拼块（模拟不同岩性面） */\n    var blk = [];\n    for (var bi = 0; bi < 4; bi++) blk.push({ x: Math.floor(rng() * W), y: Math.floor(rng() * H), r: 10 + rng() * 18 });\n    for (var y = 0; y < H; y++) for (var x = 0; x < W; x++) {\n      var nearest = 0, nd = 1e9;\n      for (var bb = 0; bb < blk.length; bb++) {\n        var d = (blk[bb].x - x) * (blk[bb].x - x) + (blk[bb].y - y) * (blk[bb].y - y);\n        if (d < nd) { nd = d; nearest = bb; }\n      }\n      bg[y * W + x] = nearest;\n      px[y * W + x] = 0; conf[y * W + x] = 0.1;\n    }\n\n    /* 裂缝：细长低对比线段，多组走向 */\n    var cracks = [];\n    var GROUPS = [35, 75, 120];   /* 三组优势走向（°） */\n    var nCr = 14 + Math.floor(rng() * 8);\n    for (var c = 0; c < nCr; c++) {\n      var grp = GROUPS[Math.floor(rng() * GROUPS.length)];\n      var ang = grp + (rng() - 0.5) * 18;   /* 组内浮动 */\n      var len = 8 + rng() * 20;\n      var x0 = 3 + rng() * (W - 6), y0 = 3 + rng() * (H - 6);\n      var aRad = ang * Math.PI / 180;\n      var dx = Math.cos(aRad), dy = Math.sin(aRad);\n      var wd = 1 + (rng() < 0.7 ? 0 : 1);    /* 大多细，少数宽 */\n      var pts = [];\n      for (var t = 0; t <= len; t += 0.5) {\n        var x = Math.round(x0 + dx * t), yy = Math.round(y0 + dy * t);\n        if (x < 0 || x >= W || yy < 0 || yy >= H) continue;\n        for (var w = 0; w <= wd; w++) {\n          var xw = x, yw = yy + w - 1;\n          if (xw < 0 || xw >= W || yw < 0 || yw >= H) continue;\n          px[yw * W + xw] = 1; conf[yw * W + xw] = 0.45 + rng() * 0.3;\n        }\n        pts.push([x, yy]);\n      }\n      if (pts.length < 4) continue;\n      cracks.push({ id: 'C' + (c + 1), angle: ang, len: len, x0: x0, y0: y0, pts: pts, wd: wd });\n    }\n\n    return { W: W, H: H, px: px, conf: conf, bg: bg, cracks: cracks, groups: GROUPS, nCrack: cracks.length };\n  }\n  M.genOutcrop = genOutcrop;\n\n  /* =========================================================\n     裂缝实例分割（模拟 Mask R-CNN）\n     ---------------------------------------------------------\n     confTh 高则保守（漏检小裂缝多），低则激进（易粘连）。\n     返回 { masks:[{crack, conf, hit}], recall, nDet }\n     ========================================================= */\n  function instanceSeg(scan, confTh, seed) {\n    var rng = mulberry32((seed || 91) + Math.round(confTh * 1000));\n    var masks = [], tp = 0;\n    for (var c = 0; c < scan.cracks.length; c++) {\n      var cr = scan.cracks[c];\n      /* 短裂缝难检；宽裂缝易检 */\n      var conf = clamp(0.85 - (cr.len < 12 ? 0.38 : 0) + (cr.wd > 0 ? 0.1 : 0) - (confTh - 0.5) * 0.6, 0.08, 0.97);\n      if (conf >= confTh) { masks.push({ crack: cr, conf: conf, hit: true }); tp++; }\n    }\n    /* 粘连：confTh 低时相邻裂缝被并成一条（少算条数） */\n    var nMerge = Math.max(0, Math.round((0.55 - confTh) * 3));\n    for (var m = 0; m < nMerge; m++) {\n      if (masks.length >= 2) { masks.splice(Math.floor(rng() * (masks.length - 1)), 1); tp--; }\n    }\n    var recall = scan.cracks.length ? tp / scan.cracks.length : 1;\n    return { masks: masks, recall: recall, tp: tp, total: scan.cracks.length };\n  }\n  M.instanceSeg = instanceSeg;\n\n  /* =========================================================\n     骨架化：裂缝掩膜 → 中心线 → 长度 / 走向\n     ---------------------------------------------------------\n     返回 [{id, angle, lenPx, skeleton:[pts]}]\n     ========================================================= */\n  function skeletonize(seg, minLen, seed) {\n    var rng = mulberry32((seed || 55) + (minLen || 2) * 7);\n    var skels = [];\n    for (var m = 0; m < seg.masks.length; m++) {\n      var cr = seg.masks[m].crack;\n      var s = cr.pts.slice();\n      /* 简化：按最小长度过滤短裂缝 */\n      if (s.length < (minLen || 2) * 2) continue;\n      skels.push({ id: cr.id, angle: cr.angle, lenPx: s.length, skeleton: s, wd: cr.wd });\n    }\n    return { skeletons: skels, nSkel: skels.length, total: seg.masks.length };\n  }\n  M.skeletonize = skeletonize;\n\n  /* =========================================================\n     产状反算 + 标定\n     ---------------------------------------------------------\n     把骨架走向换算成真实地质产状，统计走向分布。\n     calibErr 模拟标定误差：越大走向偏差越大。\n     返回 { attitudes:[{angle, deg}], rose, meanErr }\n     ========================================================= */\n  function calibAttitude(skel, calibErr, seed) {\n    var rng = mulberry32((seed || 23) + Math.round(calibErr * 100));\n    var atts = [];\n    for (var s = 0; s < skel.skeletons.length; s++) {\n      var sk = skel.skeletons[s];\n      var deg = (sk.angle + (rng() - 0.5) * calibErr * 20 + 360) % 360;\n      atts.push({ id: sk.id, angle: sk.angle, deg: deg, len: sk.lenPx });\n    }\n    /* 走向玫瑰图：按 10° 分组计数 */\n    var rose = [];\n    for (var b = 0; b < 18; b++) rose.push({ bin: b * 10, count: 0 });\n    for (var a = 0; a < atts.length; a++) {\n      var bin = Math.floor(atts[a].deg / 10) % 18;\n      rose[bin].count++;\n    }\n    var meanErr = 0, n = 0;\n    for (var aa = 0; aa < atts.length; aa++) {\n      meanErr += Math.abs(((atts[aa].deg - atts[aa].angle + 540) % 360) - 180);\n      n++;\n    }\n    meanErr = n ? meanErr / n : 0;\n    return { attitudes: atts, rose: rose, meanErr: meanErr, n: atts.length };\n  }\n  M.calibAttitude = calibAttitude;\n\n  /* =========================================================\n     实测验证：算法产状 vs 罗盘实测\n     ---------------------------------------------------------\n     返回走向误差，模拟部分实测记录作验证集。\n     ========================================================= */\n  function verifyAttitude(atts, verifyRatio, seed) {\n    var rng = mulberry32((seed || 6) + Math.round(verifyRatio * 100));\n    var nV = Math.max(1, Math.floor(atts.n * (verifyRatio || 0.3)));\n    var errSum = 0;\n    for (var v = 0; v < nV && v < atts.attitudes.length; v++) {\n      var at = atts.attitudes[v];\n      var measured = (at.angle + (rng() - 0.5) * 1.5 + 360) % 360;  /* 实测本身有 ±1.5° */\n      var d = ((at.deg - measured + 540) % 360) - 180;\n      errSum += Math.abs(d);\n    }\n    return { nV: Math.min(nV, atts.attitudes.length), meanErr: atts.n ? errSum / Math.min(nV, atts.attitudes.length) : 0 };\n  }\n  M.verifyAttitude = verifyAttitude;\n\n  return M;\n});\n\n/* =========================================================\n   浏览器接线（Node require 时走 module.exports 分支返回，不执行）\n   ========================================================= */\nif (typeof window !== 'undefined' && !window.__g4ModelOnly) {\n  (function () {\n    'use strict';\n    var M = window.Model;\n    var doc = document;\n\n    function $(id) { return doc.getElementById(id); }\n    function num(v, n) { return Number(v).toFixed(n === undefined ? 2 : n); }\n    function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\n\n    var SCALE = 8;   /* 栅格 64×48 → 512×384 */\n    var SCAN = M.genOutcrop(20261105, 64, 48);\n    var BG_COLORS = ['#d8c8a8', '#c9c4b0', '#cdbfa0', '#d2c4ae'];\n\n    /* UI 状态 */\n    var segState = { confTh: 0.5 };\n    var skelState = { minLen: 2 };\n    var calibState = { calibErr: 0.3, verifyRatio: 0.3 };\n\n    /* 屏 1 渲染：裂缝实例分割 */\n    function renderSeg() {\n      var seg = M.instanceSeg(SCAN, segState.confTh, 20261105);\n      var s = '';\n      /* 岩面背景 */\n      for (var y = 0; y < 48; y++) for (var x = 0; x < 64; x++) {\n        var i = y * 64 + x;\n        s += '<rect x=\"' + (x * SCALE) + '\" y=\"' + (y * SCALE) + '\" width=\"' + SCALE + '\" height=\"' + SCALE + '\" fill=\"' + BG_COLORS[SCAN.px[i] === 1 ? 0 : SCAN.bg[i] % BG_COLORS.length] + '\" opacity=\"' + (SCAN.px[i] === 1 ? 0.7 : 1) + '\"/>';\n      }\n      /* 已检出的裂缝掩膜（绿色） */\n      for (var m = 0; m < seg.masks.length; m++) {\n        var cr = seg.masks[m].crack;\n        var path = '';\n        for (var p = 0; p < cr.pts.length; p++) {\n          path += (p ? 'L' : 'M') + (cr.pts[p][0] * SCALE) + ' ' + (cr.pts[p][1] * SCALE);\n        }\n        s += '<path d=\"' + path + '\" fill=\"none\" stroke=\"#2f7d6b\" stroke-width=\"' + ((cr.wd + 1) * SCALE * 0.6) + '\" stroke-linecap=\"round\" opacity=\"0.85\"/>';\n      }\n      /* 漏检裂缝（灰虚线） */\n      var detSet = new Set(seg.masks.map(function (m) { return m.crack.id; }));\n      for (var c = 0; c < SCAN.cracks.length; c++) {\n        if (detSet.has(SCAN.cracks[c].id)) continue;\n        var cr2 = SCAN.cracks[c];\n        var path2 = '';\n        for (var q = 0; q < cr2.pts.length; q++) path2 += (q ? 'L' : 'M') + (cr2.pts[q][0] * SCALE) + ' ' + (cr2.pts[q][1] * SCALE);\n        s += '<path d=\"' + path2 + '\" fill=\"none\" stroke=\"#9ba3a9\" stroke-width=\"1.6\" stroke-dasharray=\"4 3\" opacity=\"0.7\"/>';\n      }\n      $('segChart').innerHTML = s;\n      $('roSegRecall').textContent = num(seg.recall * 100, 0) + '%';\n      $('roSegDet').textContent = seg.tp + ' / ' + seg.total;\n      $('outSegConf').textContent = num(segState.confTh, 2);\n      $('segTip').textContent = '绿色 = 检出的裂缝掩膜，灰色虚线 = 漏检裂缝。阈值越高越保守（小裂缝漏检多），越低越激进（易粘连少条数）。';\n    }\n\n    /* 屏 2 渲染：骨架化 + 线密度 */\n    function renderSkel() {\n      var seg = M.instanceSeg(SCAN, segState.confTh, 20261105);\n      var skel = M.skeletonize(seg, skelState.minLen, 55);\n      var s = '';\n      /* 岩面背景 */\n      for (var y = 0; y < 48; y++) for (var x = 0; x < 64; x++) {\n        var i = y * 64 + x;\n        s += '<rect x=\"' + (x * SCALE) + '\" y=\"' + (y * SCALE) + '\" width=\"' + SCALE + '\" height=\"' + SCALE + '\" fill=\"' + BG_COLORS[SCAN.bg[i] % BG_COLORS.length] + '\" opacity=\"0.35\"/>';\n      }\n      /* 骨架中心线 */\n      for (var sk = 0; sk < skel.skeletons.length; sk++) {\n        var sko = skel.skeletons[sk];\n        var path = '';\n        for (var p = 0; p < sko.skeleton.length; p++) {\n          path += (p ? 'L' : 'M') + (sko.skeleton[p][0] * SCALE) + ' ' + (sko.skeleton[p][1] * SCALE);\n        }\n        s += '<path d=\"' + path + '\" fill=\"none\" stroke=\"#41699b\" stroke-width=\"2.2\" stroke-linecap=\"round\"/>';\n        s += '<text x=\"' + (sko.skeleton[0][0] * SCALE + 4) + '\" y=\"' + (sko.skeleton[0][1] * SCALE - 4) + '\" font-size=\"9\" fill=\"#2b4a72\">' + sko.id + '<\/text>';\n      }\n      $('skelChart').innerHTML = s;\n      $('roSkelCount').textContent = skel.nSkel + ' 条';\n      $('roSkelFiltered').textContent = (seg.masks.length - skel.nSkel) + ' 条过滤';\n      $('outMinLen').textContent = skelState.minLen;\n      $('skelTip').textContent = '蓝色 = 裂缝骨架中心线。最小长度过滤掉过短裂缝；骨架质量决定长度与走向量得准不准。';\n    }\n\n    /* 屏 3 渲染：产状反算 + 验证 */\n    function renderCalib() {\n      var seg = M.instanceSeg(SCAN, segState.confTh, 20261105);\n      var skel = M.skeletonize(seg, skelState.minLen, 55);\n      var atts = M.calibAttitude(skel, calibState.calibErr, 23);\n      var ver = M.verifyAttitude(atts, calibState.verifyRatio, 6);\n      var s = '';\n      /* 走向玫瑰图（10° 分组） */\n      var cx = 250, cy = 190, R = 130;\n      s += '<circle cx=\"' + cx + '\" cy=\"' + cy + '\" r=\"' + R + '\" fill=\"none\" stroke=\"#e0d9c8\"/>';\n      /* 分组背景格 */\n      for (var g = 0; g < 18; g++) {\n        var a0 = (g * 10) * Math.PI / 180 - Math.PI / 2;\n        s += '<line x1=\"' + cx + '\" y1=\"' + cy + '\" x2=\"' + (cx + Math.cos(a0) * R) + '\" y2=\"' + (cy + Math.sin(a0) * R) + '\" stroke=\"#eee8db\" stroke-width=\"0.5\"/>';\n      }\n      var maxCount = 1;\n      for (var b = 0; b < atts.rose.length; b++) if (atts.rose[b].count > maxCount) maxCount = atts.rose[b].count;\n      for (var bb = 0; bb < atts.rose.length; bb++) {\n        var cnt = atts.rose[bb].count;\n        var aM = (bb * 10 + 5) * Math.PI / 180 - Math.PI / 2;\n        var rInner = R * 0.06, rOuter = R * 0.06 + (cnt / maxCount) * (R * 0.8);\n        var col = '#b26a39';\n        s += '<path d=\"M' + (cx + Math.cos(aM - 0.09) * rInner) + ' ' + (cy + Math.sin(aM - 0.09) * rInner) +\n             'L' + (cx + Math.cos(aM - 0.09) * rOuter) + ' ' + (cy + Math.sin(aM - 0.09) * rOuter) +\n             'A' + rOuter + ',' + rOuter + ' 0 0 1 ' + (cx + Math.cos(aM + 0.09) * rOuter) + ' ' + (cy + Math.sin(aM + 0.09) * rOuter) +\n             'L' + (cx + Math.cos(aM + 0.09) * rInner) + ' ' + (cy + Math.sin(aM + 0.09) * rInner) +\n             'A' + rInner + ',' + rInner + ' 0 0 0 ' + (cx + Math.cos(aM - 0.09) * rInner) + ' ' + (cy + Math.sin(aM - 0.09) * rInner) + 'Z\" fill=\"' + col + '\" opacity=\"0.75\"/>';\n      }\n      /* 角度标注 */\n      for (var gd = 0; gd < 4; gd++) {\n        var gA = gd * 45 * Math.PI / 180 - Math.PI / 2;\n        s += '<text x=\"' + (cx + Math.cos(gA) * (R + 12)) + '\" y=\"' + (cy + Math.sin(gA) * (R + 12)) + '\" font-size=\"9\" fill=\"#9ba3a9\" text-anchor=\"middle\">' + (gd * 45) + '°<\/text>';\n      }\n      s += '<text x=\"' + cx + '\" y=\"' + (cy - R - 20) + '\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\" text-anchor=\"middle\">走向玫瑰图（每 10° 一组）<\/text>';\n      $('calibChart').innerHTML = s;\n      $('roAttN').textContent = atts.n + ' 条';\n      $('roMeanErr').textContent = num(atts.meanErr, 1) + '°';\n      $('roVerErr').textContent = num(ver.meanErr, 1) + '°';\n      $('outCalibErr').textContent = num(calibState.calibErr, 2);\n      $('outVerify').textContent = num(calibState.verifyRatio, 2);\n      $('calibTip').textContent = '玫瑰图显示裂缝走向分布（35°/75°/120° 三组）。标定误差越大走向偏差越大；实测验证集用于校准误差到 ≤3°。';\n    }\n\n    /* 事件绑定 */\n    function bind() {\n      var inSeg = $('pSegConf');\n      if (inSeg) inSeg.addEventListener('input', function () {\n        segState.confTh = parseFloat(inSeg.value);\n        renderSeg(); renderSkel(); renderCalib();\n      });\n      var inMin = $('pMinLen');\n      if (inMin) inMin.addEventListener('input', function () {\n        skelState.minLen = parseInt(inMin.value, 10);\n        renderSkel(); renderCalib();\n      });\n      var inCalib = $('pCalibErr');\n      if (inCalib) inCalib.addEventListener('input', function () {\n        calibState.calibErr = parseFloat(inCalib.value);\n        renderCalib();\n      });\n      var inVer = $('pVerify');\n      if (inVer) inVer.addEventListener('input', function () {\n        calibState.verifyRatio = parseFloat(inVer.value);\n        renderCalib();\n      });\n    }\n\n    /* 抽屉上报 */\n    function setupDrawer() {\n      if (window.parent === window) return;\n      var secs = [];\n      [['sec1', '实例分割', 'segCtl'], ['sec2', '骨架化', 'skelCtl'], ['sec3', '产状反算', 'calibCtl']].forEach(function (s) {\n        var el = $(s[2]); if (!el) return;\n        el.querySelectorAll('input, button').forEach(function (c) {\n          if (c.type === 'range') c.setAttribute('value', c.value);\n        });\n        secs.push({ id: s[0], title: s[1], html: el.outerHTML, top: el.offsetTop, height: el.offsetHeight });\n      });\n      try { parent.postMessage({ __drawer: 'init', sections: secs }, '*'); } catch (e) {}\n      window.addEventListener('message', function (e) {\n        if (e.source !== window.parent) return;\n        var d = e.data;\n        if (!d || d.__drawer !== 'control') return;\n        var el = doc.querySelector('[data-ctl-id=\"' + d.id + '\"]');\n        if (!el) return;\n        if (el.type === 'range') { el.value = d.value; el.dispatchEvent(new Event('input', { bubbles: true })); }\n      });\n    }\n\n    /* 启动 */\n    renderSeg(); renderSkel(); renderCalib(); bind(); setupDrawer();\n\n    /* 桥接对象：暴露模型层给 flow.js */\n    window.RemoteBridge = { M: M, live: function () { return { confTh: segState.confTh, minLen: skelState.minLen, calibErr: calibState.calibErr, verifyRatio: calibState.verifyRatio }; } };\n  })();\n}\n"},{"name":"demo/flow.js","mime":"text/javascript","data":"/* =========================================================\n   露头裂缝自动统计 · 算法解剖（分割 + 骨架 + 标定）\n   ---------------------------------------------------------\n   把「露头照片 → 裂缝统计」拆成 6 步，每一步都跑真代码：\n\n     ① 数据采集        多角度照片 + 点云 + 标定板\n     ② 裂缝实例分割    每条裂缝一个掩膜\n     ③ 骨架化          提炼裂缝中心线、量长度\n     ④ 摄影测量标定    像素 → 真实方位与尺度\n     ⑤ 产状反算 + 统计  走向玫瑰图 + 线密度\n     ⑥ 实测验证        罗盘实测校准走向误差\n\n   依赖：window.RemoteBridge（demo.js 暴露的真模型）\n        window.AFlow（算法解剖引擎）\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  var B = global.RemoteBridge;\n  if (!B || !global.AFlow) return;\n\n  var G = global.AFlow.G, C = global.AFlow.C;\n  var M = B.M;\n\n  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\n  function f(v, n) { return (v == null || !isFinite(v)) ? '—' : Number(v).toFixed(n === undefined ? 2 : n); }\n\n  function hexA(hex, a) {\n    var r = parseInt(hex.slice(1, 3), 16), g = parseInt(hex.slice(3, 5), 16), b = parseInt(hex.slice(5, 7), 16);\n    return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';\n  }\n\n  /* 面板底部小结框 */\n  function footBox(x, w, y, h, title, lines, tone) {\n    var bg = tone === 'jade' ? C.jadeL : tone === 'clay' ? C.clayL : tone === 'blue' ? C.blueL : '#f4f3ef';\n    var st = tone === 'jade' ? '#b9d8cb' : tone === 'clay' ? '#e6cdb2' : tone === 'blue' ? '#c5d6ea' : C.line;\n    var fg = tone === 'jade' ? C.jadeD : tone === 'clay' ? '#8a4f27' : tone === 'blue' ? '#2b4a72' : C.ink2;\n    var s = G.rect(x, y, w, h, { r: 6, fill: bg, stroke: st });\n    if (title) s += G.txt(x + 11, y + 17, title, { size: 9.6, fill: fg, weight: 700 });\n    for (var i = 0; i < lines.length; i++) {\n      s += G.txt(x + 11, y + (title ? 33 : 17) + i * 13, lines[i], { size: 8.8, fill: fg });\n    }\n    return s;\n  }\n\n  /* 露头岩面底图 */\n  var BG_COLORS = ['#d8c8a8', '#c9c4b0', '#cdbfa0', '#d2c4ae'];\n  function rockBase(scan, W, H, S, x0, y0) {\n    var s = '';\n    for (var y = 0; y < H; y++) {\n      for (var x = 0; x < W; x++) {\n        var i = y * W + x;\n        s += G.rect(x0 + x * S, y0 + y * S, S, S, { fill: BG_COLORS[scan.bg[i] % BG_COLORS.length], op: 1 });\n      }\n    }\n    return s;\n  }\n\n  var W = 48, H = 36, S = 7;   /* 露头区 48×36 → SVG 336×252 */\n\n  /* ---------- 缓存 ---------- */\n  var cache = { key: '' };\n  function compute() {\n    var L = B.live();\n    var key = [L.confTh, L.minLen, L.calibErr, L.verifyRatio].join(',');\n    if (cache.key === key) return cache;\n    var scan = M.genOutcrop(20261105, W, H);\n    var seg = M.instanceSeg(scan, L.confTh, 91);\n    var skel = M.skeletonize(seg, L.minLen, 55);\n    var atts = M.calibAttitude(skel, L.calibErr, 23);\n    var ver = M.verifyAttitude(atts, L.verifyRatio, 6);\n    cache = { key: key, L: L, scan: scan, seg: seg, skel: skel, atts: atts, ver: ver };\n    return cache;\n  }\n\n  /* =========================================================\n     ① 数据采集\n     ========================================================= */\n  function stage1(t) {\n    var c = compute(), scan = c.scan, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 多角度照片', '含标定板', C.blue);\n    s += G.panel(1, '② 无人机点云', '厘米级 · 无需标注', C.jade);\n    s += G.panel(2, '③ 裂缝标注', '掩膜 ≥1000 条', C.clay);\n\n    var x0 = 30, y0 = 132;\n    s += rockBase(scan, W, H, S, x0, y0);\n    /* 裂缝真值（灰线） */\n    for (var c2 = 0; c2 < scan.cracks.length; c2++) {\n      var cr = scan.cracks[c2];\n      var path = '';\n      for (var p = 0; p < cr.pts.length; p++) path += (p ? 'L' : 'M') + (x0 + cr.pts[p][0] * S) + ' ' + (y0 + cr.pts[p][1] * S);\n      s += G.path(path, { fill: 'none', stroke: '#9ba3a9', sw: 1.3 });\n    }\n    s += G.txt(x0, y0 - 12, '露头裂缝照片 · ' + scan.nCrack + ' 条裂缝 · 3 组优势走向', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(330, 260, 132, 192, '采集的现实',\n      ['· 200—500 张多角度照片',\n       '  含标定板才能标定',\n       '· 无人机点云厘米级',\n       '  覆盖整个露面',\n       '',\n       '裂缝掩膜 ≥ 1000 条，',\n       '分割模型才有得学。'], 'blue');\n\n    s += G.txt(x0, y0 + 208, '第一步把露头拍全、标定好——照片供分割，点云供几何标定', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '裂缝', v: scan.nCrack + ' 条' }, { k: '走向组', v: '3 组' }, { k: '掩膜', v: '≥1000' }], note: '数据采集覆盖多角度照片（含标定板）与无人机点云——照片喂分割模型，点云提供几何标定基准，裂缝掩膜是训练数据。' };\n  }\n\n  /* =========================================================\n     ② 裂缝实例分割\n     ========================================================= */\n  function stage2(t) {\n    var c = compute(), scan = c.scan, seg = c.seg, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 露头照片', '输入', C.blue);\n    s += G.panel(1, '② Mask R-CNN', '像素级分割', C.jade);\n    s += G.panel(2, '③ 裂缝掩膜', '每条一条 · 可数', C.clay);\n\n    var x0 = 30, y0 = 132;\n    s += rockBase(scan, W, H, S, x0, y0);\n    /* 漏检（灰虚线） */\n    var detSet = new Set(seg.masks.map(function (m) { return m.crack.id; }));\n    for (var c3 = 0; c3 < scan.cracks.length; c3++) {\n      if (detSet.has(scan.cracks[c3].id)) continue;\n      var cr3 = scan.cracks[c3];\n      var path3 = '';\n      for (var q = 0; q < cr3.pts.length; q++) path3 += (q ? 'L' : 'M') + (x0 + cr3.pts[q][0] * S) + ' ' + (y0 + cr3.pts[q][1] * S);\n      s += G.path(path3, { fill: 'none', stroke: '#9ba3a9', sw: 1.4, dash: '4 3' });\n    }\n    /* 检出掩膜（绿） */\n    for (var m = 0; m < seg.masks.length; m++) {\n      var cr = seg.masks[m].crack;\n      var path = '';\n      for (var p = 0; p < cr.pts.length; p++) path += (p ? 'L' : 'M') + (x0 + cr.pts[p][0] * S) + ' ' + (y0 + cr.pts[p][1] * S);\n      s += G.path(path, { fill: 'none', stroke: '#2f7d6b', sw: (cr.wd + 1) * S * 0.55, cap: 'round' });\n    }\n    s += G.txt(x0, y0 - 12, '实例分割 · 检出 ' + seg.tp + '/' + seg.total + ' · 阈值 ' + f(L.confTh, 2), { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(330, 260, 132, 192, '分割的现实',\n      ['· 裂缝细长、低对比',\n       '  与岩面背景接近',\n       '· 短裂缝、小开度难检',\n       '  易漏或粘连成一条',\n       '',\n       '阈值高漏检多，',\n       '低则粘连少条数。'], 'clay');\n\n    s += G.txt(x0, y0 + 208, '实例分割把每条裂缝从岩面抠成单独掩膜——条数、形态都可数可量', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '检出', v: seg.tp + '/' + seg.total }, { k: '召回', v: f(seg.recall * 100, 0) + '%' }, { k: '阈值', v: f(L.confTh, 2) }], note: '实例分割（Mask R-CNN）把每条裂缝从岩面背景抠成单独掩膜。难点在裂缝细长低对比——短裂缝易漏、交叉处易粘连。' };\n  }\n\n  /* =========================================================\n     ③ 骨架化\n     ========================================================= */\n  function stage3(t) {\n    var c = compute(), seg = c.seg, skel = c.skel, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 裂缝掩膜', '输入', C.blue);\n    s += G.panel(1, '② 细化骨架', '提取中心线', C.jade);\n    s += G.panel(2, '③ 长度 + 走向', '线密度统计', C.clay);\n\n    var x0 = 30, y0 = 132;\n    /* 岩面背景（淡） */\n    s += rockBase(c.scan, W, H, S, x0, y0);\n    /* 骨架中心线 */\n    for (var sk = 0; sk < skel.skeletons.length; sk++) {\n      var sko = skel.skeletons[sk];\n      var path = '';\n      for (var p = 0; p < sko.skeleton.length; p++) path += (p ? 'L' : 'M') + (x0 + sko.skeleton[p][0] * S) + ' ' + (y0 + sko.skeleton[p][1] * S);\n      s += G.path(path, { fill: 'none', stroke: '#41699b', sw: 2, cap: 'round' });\n      s += G.txt(x0 + sko.skeleton[0][0] * S + 3, y0 + sko.skeleton[0][1] * S - 4, sko.id, { size: 7.5, fill: '#2b4a72', weight: 700 });\n    }\n    s += G.txt(x0, y0 - 12, '骨架化 · ' + skel.nSkel + ' 条骨架 · 过滤 ' + (seg.masks.length - skel.nSkel) + ' 条', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(330, 260, 132, 192, '骨架的现实',\n      ['· 掩膜细化出中心线',\n       '  一条裂缝一条线',\n       '· 长度 = 中心线像素数',\n       '· 走向 = 中心线方向',\n       '',\n       '分叉 / 交叉处骨架',\n       '易错，长度走向量偏。'], 'jade');\n\n    s += G.txt(x0, y0 + 208, '骨架化把裂缝掩膜提炼成中心线——长度、走向、线密度都从这条线算', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '骨架', v: skel.nSkel + ' 条' }, { k: '过滤', v: seg.masks.length - skel.nSkel + ' 条' }, { k: 'minLen', v: L.minLen }], note: '骨架化对掩膜做细化，提炼出裂缝中心线。长度与走向都从中心线量取——分叉、交叉处骨架易错，是线密度统计的主要误差来源。' };\n  }\n\n  /* =========================================================\n     ④ 摄影测量标定\n     ========================================================= */\n  function stage4(t) {\n    var c = compute(), scan = c.scan, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 标定板 + 点云', '几何基准', C.blue);\n    s += G.panel(1, '② 相机标定', '内外参 + 尺度', C.jade);\n    s += G.panel(2, '③ 像素 → 产状', '真实方位 / 尺度', C.clay);\n\n    var x0 = 30, y0 = 132;\n    /* 标定示意图：棋盘格 */\n    var cbx = x0 + 20, cby = y0 + 40, cbs = 22;\n    for (var r = 0; r < 4; r++) {\n      for (var c4 = 0; c4 < 4; c4++) {\n        var fill = (r + c4) % 2 === 0 ? '#2b2b2b' : '#f4f1e6';\n        s += G.rect(cbx + c4 * cbs, cby + r * cbs, cbs, cbs, { fill: fill, r: 0 });\n      }\n    }\n    s += G.txt(cbx + 2 * cbs, cby + 4 * cbs + 14, '标定板（几何基准）', { size: 8, fill: C.ink3, anchor: 'middle' });\n    /* 点云示意 */\n    var px0 = x0 + 300, py0 = y0 + 100;\n    for (var d = 0; d < 30; d++) {\n      var ax = px0 + Math.sin(d * 1.7) * 46 + (Math.sin(d * 0.9) * 30);\n      var ay = py0 + Math.cos(d * 1.1) * 30 + (Math.sin(d * 2.3) * 20);\n      s += G.circle(ax, ay, 1.1, { fill: '#41699b', op: 0.8 });\n    }\n    s += G.txt(px0, py0 + 46, '无人机点云（厘米级）', { size: 8, fill: C.ink3, anchor: 'middle' });\n    s += G.txt(x0, y0 - 12, '摄影测量标定 · 标定误差 ' + f(L.calibErr, 2), { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(330, 260, 132, 192, '标定的现实',\n      ['· 像素距离 ≠ 真实产状',\n       '· 必须用标定板 + 点云',\n       '  完成相机内外参标定',\n       '',\n       '缺基准时走向 / 开度',\n       '整体偏差，统计失真。'], 'blue');\n\n    s += G.txt(x0, y0 + 208, '标定把「像素距离」换算成「真实方位与尺度」——产状反算的几何前提', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '标定板', v: '几何基准' }, { k: '点云', v: '厘米级' }, { k: '标定误差', v: f(L.calibErr, 2) }], note: '摄影测量标定用标定板与点云把像素几何换算成真实方位与尺度。缺基准时像素≠产状，算出的走向与开度会整体偏差——这是裂缝统计最关键的工程环节。' };\n  }\n\n  /* =========================================================\n     ⑤ 产状反算 + 统计\n     ========================================================= */\n  function stage5(t) {\n    var c = compute(), atts = c.atts, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 骨架走向', '每条裂缝', C.blue);\n    s += G.panel(1, '② 产状换算', '标定 + 方位', C.jade);\n    s += G.panel(2, '③ 走向玫瑰图', '分布 + 线密度', C.clay);\n\n    var x0 = 30, y0 = 132, cx = x0 + 168, cy = y0 + 126, R = 108;\n    /* 玫瑰图 */\n    s += G.circle(cx, cy, R, { fill: '#fbfaf6', stroke: '#e0d9c8', sw: 1 });\n    for (var g = 0; g < 18; g++) {\n      var a0 = (g * 10) * Math.PI / 180 - Math.PI / 2;\n      s += G.line(cx, cy, cx + Math.cos(a0) * R, cy + Math.sin(a0) * R, { stroke: '#eee8db', sw: 0.6 });\n    }\n    var maxCount = 1;\n    for (var b = 0; b < atts.rose.length; b++) if (atts.rose[b].count > maxCount) maxCount = atts.rose[b].count;\n    for (var bb = 0; bb < atts.rose.length; bb++) {\n      var cnt = atts.rose[bb].count;\n      if (cnt === 0) continue;\n      var aM = (bb * 10 + 5) * Math.PI / 180 - Math.PI / 2;\n      var rIn = R * 0.06, rOut = R * 0.06 + (cnt / maxCount) * (R * 0.8);\n      s += G.path('M' + (cx + Math.cos(aM - 0.09) * rIn).toFixed(1) + ' ' + (cy + Math.sin(aM - 0.09) * rIn).toFixed(1) +\n        'L' + (cx + Math.cos(aM - 0.09) * rOut).toFixed(1) + ' ' + (cy + Math.sin(aM - 0.09) * rOut).toFixed(1) +\n        'A' + rOut.toFixed(1) + ',' + rOut.toFixed(1) + ' 0 0 1 ' + (cx + Math.cos(aM + 0.09) * rOut).toFixed(1) + ' ' + (cy + Math.sin(aM + 0.09) * rOut).toFixed(1) +\n        'L' + (cx + Math.cos(aM + 0.09) * rIn).toFixed(1) + ' ' + (cy + Math.sin(aM + 0.09) * rIn).toFixed(1) +\n        'A' + rIn.toFixed(1) + ',' + rIn.toFixed(1) + ' 0 0 0 ' + (cx + Math.cos(aM - 0.09) * rIn).toFixed(1) + ' ' + (cy + Math.sin(aM - 0.09) * rIn).toFixed(1) + 'Z',\n        { fill: '#b26a39', op: 0.75 });\n    }\n    for (var gd = 0; gd < 4; gd++) {\n      var gA = gd * 45 * Math.PI / 180 - Math.PI / 2;\n      s += G.txt(cx + Math.cos(gA) * (R + 14), cy + Math.sin(gA) * (R + 14), (gd * 45) + '°', { size: 8, fill: '#9ba3a9', anchor: 'middle' });\n    }\n    s += G.txt(cx, cy - R - 14, '走向玫瑰图', { size: 9.5, fill: C.ink2, weight: 700, anchor: 'middle' });\n    s += G.txt(x0, y0 - 12, '产状反算 · ' + atts.n + ' 条 · 平均走向误差 ' + f(atts.meanErr, 1) + '°', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(330, 260, 132, 192, '统计的现实',\n      ['· 玫瑰图 = 走向分布',\n       '  3 组优势走向清晰',\n       '· 线密度 = 单位面积条数',\n       '',\n       '走向分布对投影方向',\n       '敏感，需按组统计。'], 'clay');\n\n    s += G.txt(x0, y0 + 208, '产状反算把每条裂缝的走向换算成真实地质产状——玫瑰图直接看分布', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '裂缝', v: atts.n + ' 条' }, { k: '走向误差', v: f(atts.meanErr, 1) + '°' }, { k: '走向组', v: '35/75/120°' }], note: '产状反算把骨架走向换算成真实地质产状，统计走向玫瑰图与线密度。走向分布对投影方向敏感——要按裂缝分组统计，避免不同组误差互相掩盖。' };\n  }\n\n  /* =========================================================\n     ⑥ 实测验证\n     ========================================================= */\n  function stage6(t) {\n    var c = compute(), atts = c.atts, ver = c.ver, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 算法产状', '自动统计', C.blue);\n    s += G.panel(1, '② 罗盘实测', '100—200 条验证集', C.jade);\n    s += G.panel(2, '③ 校准 + 回写', '误差 ≤3°', C.clay);\n\n    var x0 = 30, y0 = 132;\n    /* 算法 vs 实测走向对比散点 */\n    var nShow = Math.min(atts.attitudes.length, 16);\n    var chartW = 250, chartH = 60, bx = x0 + 20, by = y0 + 90;\n    /* 轴 */\n    s += G.rect(bx, by, chartW, chartH, { r: 4, fill: '#fbfaf6', stroke: '#e0d9c8' });\n    s += G.txt(bx + 4, by - 6, '算法产状 vs 罗盘实测走向（每条裂缝）', { size: 8.5, fill: C.ink3, weight: 700 });\n    for (var i = 0; i < nShow; i++) {\n      var at = atts.attitudes[i];\n      var gx = bx + 8 + i * ((chartW - 16) / Math.max(1, nShow - 1));\n      var gyAlg = by + chartH - (at.deg % 180) / 180 * (chartH - 12) - 6;\n      var gyM = by + chartH - (at.angle % 180) / 180 * (chartH - 12) - 6;\n      s += G.line(gx, gyAlg, gx, gyM, { stroke: '#d8c4ae', sw: 1.4 });\n      s += G.circle(gx, gyAlg, 2.4, { fill: '#b26a39' });\n      s += G.circle(gx, gyM, 2.2, { fill: '#2f7d6b' });\n    }\n    /* 图例 */\n    s += G.circle(bx + 8, by + chartH + 12, 2.5, { fill: '#b26a39' });\n    s += G.txt(bx + 14, by + chartH + 16, '算法', { size: 8, fill: '#8a4f27' });\n    s += G.circle(bx + 60, by + chartH + 12, 2.5, { fill: '#2f7d6b' });\n    s += G.txt(bx + 66, by + chartH + 16, '罗盘实测', { size: 8, fill: '#22604f' });\n    s += G.txt(x0, y0 - 12, '实测验证 · 抽检 ' + ver.nV + ' 条 · 走向误差 ' + f(ver.meanErr, 1) + '°', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(330, 260, 132, 192, '验证的现实',\n      ['· 罗盘实测 100—200 条',\n       '  作验证集校准',\n       '· 走向误差目标 ≤3°',\n       '  （人工本身 ±1.5°）',\n       '',\n       '只自动不实测，误差',\n       '不被发现，建模用错。'], 'jade');\n\n    s += G.txt(x0, y0 + 208, '罗盘实测校准算法产状——误差 ≤3°，修正样本回写训练集', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '抽检', v: ver.nV + ' 条' }, { k: '走向误差', v: f(ver.meanErr, 1) + '°' }, { k: '目标', v: '≤3°' }], note: '最后用罗盘实测验证算法产状，校准走向误差到 ≤3°，修正样本回写训练集。只自动不实测会掩盖系统性误差——验证集是质量关口。' };\n  }\n\n  global.RemoteFlow = { stage1: stage1, stage2: stage2, stage3: stage3, stage4: stage4, stage5: stage5, stage6: stage6 };\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/index.html","mime":"text/html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>示范：露头裂缝自动统计<\/title>\n<link rel=\"stylesheet\" href=\"demo.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aflow.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aiq.css?v=20261105a\">\n<style>\n/* 右侧控件抽屉（嵌入主站时由父页面接管，这里保留独立样式兜底） */\n#ctlDrawer{position:fixed;right:0;top:70px;width:268px;max-height:calc(100vh - 120px);overflow-y:auto;background:#fff;border:1px solid #e9e4d8;border-radius:10px;box-shadow:0 6px 24px -8px rgba(0,0,0,.15);z-index:90;transform:translateX(-100%);opacity:0;pointer-events:none;transition:transform .3s ease,opacity .3s ease}\n#ctlDrawer.open{transform:translateX(0);opacity:1;pointer-events:auto}\n@media (max-width:760px){#ctlDrawer{width:calc(100vw - 20px);right:10px;top:auto;bottom:10px;max-height:45vh}}\n<\/style>\n<\/head>\n<body>\n\n<header class=\"hd\">\n  <span class=\"kicker\">CASE DEMO · 地质勘察 / 露头裂缝自动统计<\/span>\n  <h1>从「持罗盘皮尺 · 半天/露头」到「分割 + 骨架 + 标定 · 分钟级产状」<\/h1>\n  <p class=\"sub\">三个实验：Q1 看懂裂缝实例分割、Q2 看懂骨架化 + 线密度、Q3 产状反算 + 实测验证。<\/p>\n<\/header>\n\n<!-- ================= 算法解剖 · 裂缝统计全流程 ================= -->\n<section class=\"sec\" id=\"sec0\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">深入 · 想逐帧看就往下<\/span>\n    <p class=\"qa-a\">不是「照片 → 黑盒 → 统计」，而是<b>逐段展开<\/b>：数据采集 → 实例分割 → 骨架化 → 摄影测量标定 → 产状反算 → 实测验证，每一步都能看见中间量<\/p>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">可选深入 · 对应流程 STEP 2—5<\/span>\n    <h2>把「露头照片 → 裂缝统计」一步步拆开看<\/h2>\n    <p class=\"leadline\">下面这段动画跑的是<b>真代码<\/b>（与实验 1—3 同一份模型）。自动播放，也可点阶段名跳步、拖速度。改分割阈值、最小长度、标定误差和验证比例，这里的每一步都会同步重算。<\/p>\n  <\/div>\n  <div id=\"flowMount\"><\/div>\n  <details class=\"more\">\n    <summary>这段动画与后面三个实验是什么关系<\/summary>\n    <div class=\"more-body\">\n      <p>实验 1—3 给出的是<b>结果<\/b>（裂缝掩膜、骨架、玫瑰图）；这段动画给出的是<b>过程<\/b>——同一份 <code>demo.js<\/code> 里的 <code>instanceSeg / skeletonize / calibAttitude / verifyAttitude<\/code> 被拆成 6 个阶段依次放慢演给你看。<\/p>\n      <p>刻意做的两处细节：<b>①<\/b> 第 2 步用实例分割说明「每条裂缝单独抠出来」的条数逻辑；<b>②<\/b> 第 5 步用走向玫瑰图看得见 3 组优势走向，理解「标定误差怎么让玫瑰图失真」。<\/p>\n    <\/div>\n  <\/details>\n<\/section>\n\n<!-- ================= 实验 1 · 裂缝实例分割 ================= -->\n<section class=\"sec\" id=\"sec1\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q1 · 为什么需要智能算法<\/span>\n    <p class=\"qa-a\">人工逐条量半天/露头；实例分割自动把每条裂缝抠出来，分钟级<\/p>\n    <button class=\"qa-go\">开始实验 1<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 1 · 对应流程 STEP 2<\/span>\n    <h2>裂缝实例分割：每条裂缝一个掩膜<\/h2>\n    <p class=\"leadline\">拖分割阈值，看裂缝怎么从「全检出」到「漏掉小裂缝」——阈值高保守、低粘连。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"segCtl\">\n    <div class=\"sl\">\n      <label>分割阈值<output id=\"outSegConf\">0.50<\/output><\/label>\n      <input type=\"range\" id=\"pSegConf\" min=\"0.2\" max=\"0.9\" step=\"0.05\" value=\"0.5\">\n    <\/div>\n  <\/div>\n  <svg id=\"segChart\" viewBox=\"0 0 512 384\" role=\"img\" aria-label=\"裂缝实例分割结果\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">召回率<\/span><b id=\"roSegRecall\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">检出裂缝<\/span><b id=\"roSegDet\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"segTip\">绿色 = 检出的裂缝掩膜，灰色虚线 = 漏检裂缝。阈值越高越保守（小裂缝漏检多），越低越激进（易粘连少条数）。<\/p>\n<\/section>\n\n<!-- ================= 实验 2 · 骨架化 + 线密度 ================= -->\n<section class=\"sec\" id=\"sec2\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q2 · 智能算法是什么<\/span>\n    <p class=\"qa-a\"><b>骨架化<\/b> 把裂缝掩膜细化成中心线，量出长度与走向<span class=\"qa-algo\">计算机视觉 · 骨架 / 细化<\/span><\/p>\n    <button class=\"qa-go\">开始实验 2<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 2 · 对应流程 STEP 3<\/span>\n    <h2>骨架化：裂缝掩膜 → 中心线 → 长度与线密度<\/h2>\n    <p class=\"leadline\">拖最小长度过滤掉过短裂缝，看骨架怎么量出每条裂缝的长度与走向。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"skelCtl\">\n    <div class=\"sl\">\n      <label>最小长度<output id=\"outMinLen\">2<\/output><\/label>\n      <input type=\"range\" id=\"pMinLen\" min=\"1\" max=\"5\" step=\"1\" value=\"2\">\n    <\/div>\n  <\/div>\n  <svg id=\"skelChart\" viewBox=\"0 0 512 384\" role=\"img\" aria-label=\"裂缝骨架化结果\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">骨架条数<\/span><b id=\"roSkelCount\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">过滤条数<\/span><b id=\"roSkelFiltered\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"skelTip\">蓝色 = 裂缝骨架中心线。最小长度过滤掉过短裂缝；骨架质量决定长度与走向量得准不准。<\/p>\n<\/section>\n\n<!-- ================= 实验 3 · 产状反算 + 验证 ================= -->\n<section class=\"sec\" id=\"sec3\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q3 · 它怎么工作<\/span>\n    <p class=\"qa-a\">骨架走向 → 摄影测量标定 → 产状玫瑰图 + 罗盘实测验证<\/p>\n    <button class=\"qa-go\">开始实验 3<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 3 · 对应流程 STEP 4—6<\/span>\n    <h2>产状反算：像素走向怎么变成真实地质产状<\/h2>\n    <p class=\"leadline\">拖标定误差看玫瑰图怎么失真，拖验证比例看实测如何校准走向误差。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"calibCtl\">\n    <div class=\"sl\">\n      <label>标定误差<output id=\"outCalibErr\">0.30<\/output><\/label>\n      <input type=\"range\" id=\"pCalibErr\" min=\"0.05\" max=\"0.9\" step=\"0.05\" value=\"0.3\">\n    <\/div>\n    <div class=\"sl\">\n      <label>验证比例<output id=\"outVerify\">0.30<\/output><\/label>\n      <input type=\"range\" id=\"pVerify\" min=\"0.1\" max=\"0.6\" step=\"0.05\" value=\"0.3\">\n    <\/div>\n  <\/div>\n  <svg id=\"calibChart\" viewBox=\"0 0 512 384\" role=\"img\" aria-label=\"走向玫瑰图\"><\/svg>\n  <div class=\"rrow ro3\">\n    <div class=\"ro\"><span class=\"k\">统计裂缝<\/span><b id=\"roAttN\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">平均走向误差<\/span><b id=\"roMeanErr\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">实测验证误差<\/span><b id=\"roVerErr\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"calibTip\">玫瑰图显示裂缝走向分布（35°/75°/120° 三组）。标定误差越大走向偏差越大；实测验证集用于校准误差到 ≤3°。<\/p>\n<\/section>\n\n<footer>\n  <div class=\"map\">\n    <div><b>实验 1 → STEP 2<\/b><br>实例分割把每条裂缝抠成单独掩膜。<\/div>\n    <div><b>实验 2 → STEP 3<\/b><br>骨架化提炼中心线，量长度与走向。<\/div>\n    <div><b>实验 3 → STEP 4—6<\/b><br>摄影测量标定 + 产状反算 + 实测验证。<\/div>\n  <\/div>\n  <p class=\"note\">纯前端教学演示：露头照片由「岩面背景 + 裂缝线段」合成，裂缝真值（走向/长度）已知、仅供对比；实例分割、骨架化、产状反算与实测验证均在浏览器实时计算。<\/p>\n<\/footer>\n\n<script src=\"demo.js\"><\/script>\n<script src=\"aflow.js\"><\/script>\n<script src=\"flow.js\"><\/script>\n<script>\n/* 算法解剖：把 6 个阶段挂到 AFlow 引擎上 */\n(function () {\n  if (!window.AFlow || !window.RemoteFlow) return;\n  var F = window.RemoteFlow;\n  window.RemoteFlowApi = window.AFlow.create({\n    mount: document.getElementById('flowMount'),\n    title: '算法解剖',\n    subtitle: '自动播放：露头照片怎么一步步变成裂缝统计',\n    stages: [\n      { name: '数据采集', tag: '照片 + 点云', dur: 4200, draw: function (t, g) { return F.stage1(t); } },\n      { name: '实例分割', tag: '裂缝掩膜', dur: 4600, draw: function (t, g) { return F.stage2(t); } },\n      { name: '骨架化', tag: '中心线 + 长度', dur: 4400, draw: function (t, g) { return F.stage3(t); } },\n      { name: '摄影测量标定', tag: '像素 → 产状', dur: 4600, draw: function (t, g) { return F.stage4(t); } },\n      { name: '产状反算', tag: '玫瑰图 + 线密度', dur: 4600, draw: function (t, g) { return F.stage5(t); } },\n      { name: '实测验证', tag: '校准 + 回写', dur: 4400, draw: function (t, g) { return F.stage6(t); } }\n    ]\n  });\n})();\n<\/script>\n<script src=\"aiq.js?v=20261105a\"><\/script>\n<\/body>\n<\/html>\n"}];
  var CFG = {"mode":"auto","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"用合成的露头裂缝照片演示实例分割、骨架化与产状反算。","height":600};
  var META = {"id":"g4-outcrop-fracture","sceneId":"g4","title":"露头裂缝自动统计：实例分割 + 骨架化 + 产状反算"};
  var handle = null;
  var DEF = {"id":"g4-outcrop-fracture","sceneId":"g4","title":"露头裂缝自动统计：实例分割 + 骨架化 + 产状反算","methods":["cv"],"version":"1.0.0","updated":"2026-11-05","status":"ready","tabs":{"background":{"label":"专业背景","judge":[{"label":"数据形态","value":"照片 + 点云","desc":"露头多角度照片 + 无人机倾斜摄影点云"},{"label":"标注成本","value":"中","desc":"裂缝掩膜 ≥ 1000 条"},{"label":"可见收益","value":"大幅提速","desc":"从半天/露头压到分钟级"},{"label":"难度","value":"中","desc":"裂缝细长低对比，需几何标定换算产状"}],"lede":"露头裂缝的密度、走向与开度是裂缝型储层建模的关键参数，传统做法是地质人员持罗盘与皮尺逐条测量。智能方法把「人工逐条量」升级为「实例分割 + 骨架化 + 产状反算」，一个露头从半天压到分钟级，走向统计一致且无选择偏差。","sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p>露头裂缝的<b>密度、走向与开度<\/b>是裂缝型储层建模的关键参数。传统做法是地质人员持罗盘与皮尺<b>逐条测量<\/b>——爬上露头、贴皮尺、读走向，一条条记。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>测量慢<\/b>——一个露头人工测量需半天，裂缝数以百计，逐条量耗时巨大<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>选择偏差<\/b>——陡壁与高处无法靠近，测的都是容易到达的裂缝，统计结果偏差大<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>主观差异<\/b>——不同人量同一条走向可差 10° 以上，数据不可比<\/span><\/div><\/div><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"人工测量的痛点\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">人工测量：慢 · 有选择偏差 · 主观不可比<\/text><rect x=\"20\" y=\"36\" width=\"286\" height=\"180\" rx=\"8\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"163\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">持罗盘 + 皮尺逐条量<\/text><path d=\"M50 160 L150 90 L250 150\" stroke=\"#8aa77f\" stroke-width=\"2\" fill=\"none\"/><path d=\"M60 175 L160 105 L260 165\" stroke=\"#b26a39\" stroke-width=\"1.8\" fill=\"none\"/><circle cx=\"150\" cy=\"90\" r=\"8\" fill=\"none\" stroke=\"#41699b\" stroke-width=\"1.5\"/><text x=\"150\" cy=\"82\" y=\"82\" font-size=\"8.5\" fill=\"#4d565b\" text-anchor=\"middle\">罗盘<\/text><text x=\"88\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">贴皮尺量长度<\/text><text x=\"150\" y=\"205\" font-size=\"8.5\" fill=\"#8a6b52\" text-anchor=\"middle\">一个露头半天<\/text><text x=\"150\" y=\"220\" font-size=\"8.5\" fill=\"#8a6b52\" text-anchor=\"middle\">陡壁高处无法靠近<\/text><rect x=\"318\" y=\"36\" width=\"282\" height=\"180\" rx=\"8\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"459\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">测量偏差<\/text><text x=\"340\" y=\"82\" font-size=\"8.5\" fill=\"#4d565b\">同一条裂缝<\/text><text x=\"340\" y=\"100\" font-size=\"8.5\" fill=\"#4d565b\">不同人量走向<\/text><text x=\"340\" y=\"118\" font-size=\"8.5\" fill=\"#8a4f27\" font-weight=\"600\">可差 10° 以上<\/text><text x=\"340\" y=\"150\" font-size=\"8.5\" fill=\"#4d565b\">够得着的量了<\/text><text x=\"340\" y=\"168\" font-size=\"8.5\" fill=\"#4d565b\">够不着的漏掉<\/text><text x=\"340\" y=\"186\" font-size=\"8.5\" fill=\"#8a4f27\">统计有选择偏差<\/text><text x=\"459\" y=\"208\" font-size=\"8.5\" fill=\"#8a6b52\" text-anchor=\"middle\">数据主观 · 不可比<\/text><\/svg><\/div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>把「人工逐条量」换成 <b>「分割 + 骨架 + 标定」<\/b>流水线：实例分割把每条裂缝从照片里抠出来，骨架化提炼裂缝中心线，摄影测量标定把像素换算成真实产状，自动统计走向与线密度。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>裂缝实例分割<\/b>——Mask R-CNN / 分割模型把每条裂缝从岩面背景中抠成单独掩膜<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>骨架化<\/b>——对掩膜做细化，提炼裂缝中心线，量出长度与走向<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>摄影测量标定 + 产状反算<\/b>——用标定板与点云把像素几何换算成真实方位，反算产状与线密度<\/span><\/div><\/div><p>落地形态：一个露头的裂缝统计从半天压到分钟级，走向统计一致、无选择偏差，陡壁高处也能覆盖。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"裂缝统计流水线\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">照片 + 点云 → 实例分割 + 骨架化 + 标定 → 裂缝统计<\/text><rect x=\"20\" y=\"40\" width=\"140\" height=\"150\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"90\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#242b2e\" font-weight=\"600\">露头数据<\/text><text x=\"90\" y=\"80\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#79828a\">多角度照片<\/text><text x=\"90\" y=\"96\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#79828a\">+ 无人机点云<\/text><text x=\"90\" y=\"130\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">200—500 张<\/text><text x=\"90\" y=\"146\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">含标定板<\/text><path d=\"M164 115 L190 115\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"194\" y=\"40\" width=\"150\" height=\"150\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"269\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">实例分割 + 骨架<\/text><text x=\"269\" y=\"86\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">每条裂缝一个掩膜<\/text><text x=\"269\" y=\"102\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">骨架 = 中心线<\/text><text x=\"269\" y=\"128\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">量长度 / 走向<\/text><text x=\"269\" y=\"144\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">掩膜 ≥ 1000 条<\/text><path d=\"M348 115 L374 115\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"378\" y=\"40\" width=\"150\" height=\"150\" rx=\"6\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"453\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">标定 + 产状反算<\/text><text x=\"453\" y=\"86\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">标定板 + 点云<\/text><text x=\"453\" y=\"102\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">像素 → 真实方位<\/text><text x=\"453\" y=\"128\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">反算走向 / 开度<\/text><text x=\"453\" y=\"144\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">统计线密度<\/text><rect x=\"20\" y=\"204\" width=\"580\" height=\"36\" rx=\"6\" fill=\"#e7eef9\"/><text x=\"310\" y=\"226\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#2b4a72\" font-weight=\"600\">一个露头从半天压到分钟级 · 无选择偏差 · 陡壁高处全覆盖<\/text><\/svg><\/div>"},{"no":3,"en":"DATA","title":"需要准备什么","html":"<p><b>露头多角度照片<\/b>：单露头 200—500 张，含标定板，裂缝掩膜 ≥ 1000 条（实例分割训练数据）；<b>无人机倾斜摄影点云<\/b>：覆盖整个露面、厘米级分辨率，无需标注（提供几何标定基准）；<b>产状实测记录<\/b>：罗盘实测 100—200 条，作为验证集。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"数据准备\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">三类数据 + 关键现实<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#41699b\"/><text x=\"32\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">露头多角度照片<\/text><text x=\"32\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">单露头 200—500 张 · 含标定板<\/text><text x=\"32\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">裂缝掩膜 ≥ 1000 条<\/text><rect x=\"318\" y=\"34\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#2f7d6b\"/><text x=\"330\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">无人机倾斜摄影点云<\/text><text x=\"330\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">覆盖整个露面 · 厘米级<\/text><text x=\"330\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">无需标注<\/text><rect x=\"20\" y=\"106\" width=\"582\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#79828a\"/><text x=\"32\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">产状实测记录<\/text><text x=\"32\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">罗盘实测 100—200 条<\/text><text x=\"32\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">作为验证集<\/text><rect x=\"20\" y=\"184\" width=\"582\" height=\"26\" rx=\"6\" fill=\"#f8ecdf\"/><text x=\"310\" y=\"202\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">关键现实：裂缝细长低对比，且必须几何标定才能把像素换算成产状<\/text><\/svg><\/div>"},{"no":4,"en":"DIFFICULTY","title":"难度与参考方向","html":"<p>三个最容易翻车的点：<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>裂缝细长、对比度低<\/b>——与岩面背景接近，实例分割易漏或粘连，需要专门的数据增强<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>几何标定<\/b>——像素距离不等于真实产状，必须用标定板 / 点云完成相机标定，否则算出的走向不准<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>小裂缝开度<\/b>——开度小的裂缝只有几个像素，分割模型难精确量宽<\/span><\/div><\/div><p>改进路线按成本从低到高：先做 <b>实例分割 + 骨架化<\/b>（出裂缝条数与长度基线）；再加 <b>摄影测量标定<\/b>换算真实产状；最后用 <b>罗盘实测<\/b>做验证集校准走向误差、定验收口径。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"难点与对策\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">难点排序 + 成本从低到高的改进路线<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"52\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">① 裂缝细长低对比<\/text><text x=\"32\" y=\"68\" font-size=\"8.5\" fill=\"#6b4a35\">易漏 / 粘连<\/text><path d=\"M310 57 L356 57\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"34\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"52\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">实例分割 + 骨架化<\/text><text x=\"372\" y=\"68\" font-size=\"8.5\" fill=\"#4d565b\">裂缝条数 / 长度基线<\/text><rect x=\"20\" y=\"86\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"104\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">② 几何标定<\/text><text x=\"32\" y=\"120\" font-size=\"8.5\" fill=\"#6b4a35\">像素 ≠ 真实产状<\/text><path d=\"M310 109 L356 109\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"86\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"104\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">摄影测量标定<\/text><text x=\"372\" y=\"120\" font-size=\"8.5\" fill=\"#4d565b\">像素 → 真实产状<\/text><rect x=\"20\" y=\"138\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"156\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">③ 小裂缝开度<\/text><text x=\"32\" y=\"172\" font-size=\"8.5\" fill=\"#6b4a35\">仅几个像素<\/text><path d=\"M310 161 L356 161\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"138\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"156\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">罗盘实测验证集<\/text><text x=\"372\" y=\"172\" font-size=\"8.5\" fill=\"#4d565b\">校准走向 / 定口径<\/text><rect x=\"20\" y=\"192\" width=\"582\" height=\"16\" rx=\"8\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"310\" y=\"204\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#41699b\">实例分割+骨架 → 摄影测量标定 → 罗盘实测验证<\/text><\/svg><\/div>"}]},"workflow":{"label":"案例流程","title":"案例：一个裂缝型露头的自动化测量改造","lead":["某裂缝型储层研究区有 300 多个露头，此前靠地质人员持罗盘与皮尺逐条测量，每个露头半天、陡壁高处测不到、不同人量走向差 10°。目标：用实例分割 + 骨架化 + 摄影测量标定，把一个露头的裂缝统计压到分钟级，走向统计一致、覆盖陡壁高处。","注意第 2、3、4 步：实例分割、骨架化 + 线密度、摄影测量标定 + 产状反算是智能化价值的三个落点，示范页三屏一一对应。"],"stats":[["露头数量","300+ 个"],["人工测量","半天/露头"],["裂缝掩膜","≥1000 条"],["自动统计","分钟级"],["产状实测","100—200 条"],["走向误差","≤3°"]],"steps":[{"name":"露头数据采集","role":"数据","do":"用多角度照片（200—500 张，含标定板）+ 无人机倾斜摄影点云覆盖整个露头，标注裂缝掩膜（≥1000 条）。示范页屏 1 展示露头照片与裂缝标注。","effect":"一套含标定信息的多角度露头影像与点云，供分割与标定使用。","trap":"照片缺少标定板，后续无法把像素换算成真实产状。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">数据采集：多角度照片 + 点云 + 标定板<\/text><rect x=\"24\" y=\"42\" width=\"170\" height=\"70\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"109\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">多角度照片<\/text><text x=\"109\" y=\"78\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">200—500 张 · 含标定板<\/text><text x=\"109\" y=\"94\" text-anchor=\"middle\" font-size=\"8\" fill=\"#9ba3a9\">裂缝掩膜 ≥ 1000 条<\/text><path d=\"M198 77 L222 77\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"226\" y=\"42\" width=\"170\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"311\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">无人机点云<\/text><text x=\"311\" y=\"78\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">倾斜摄影 · 厘米级<\/text><text x=\"311\" y=\"94\" text-anchor=\"middle\" font-size=\"8\" fill=\"#9ba3a9\">覆盖整个露面<\/text><path d=\"M400 77 L424 77\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"428\" y=\"42\" width=\"168\" height=\"70\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"512\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">标定板<\/text><text x=\"512\" y=\"78\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">几何标定基准<\/text><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：照片缺标定板 → 像素无法换算成真实产状<\/text><\/svg>"},{"name":"裂缝实例分割","role":"算法核心","do":"用实例分割（Mask R-CNN / 分割模型）把每条裂缝从岩面背景中抠成单独掩膜。示范页屏 1 实时分割合成露头照片上的裂缝。","effect":"每条裂缝一个掩膜，裂缝条数与形态可数可量。","trap":"裂缝细长、与岩面低对比，易漏或粘连成一条。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">实例分割：露头照片 → 每条裂缝一个掩膜<\/text><rect x=\"24\" y=\"42\" width=\"170\" height=\"70\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"109\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">露头照片<\/text><path d=\"M60 88 L150 56 M200 84 L130 48\" stroke=\"#9ba3a9\" stroke-width=\"1.4\" fill=\"none\"/><path d=\"M80 96 L170 66\" stroke=\"#b26a39\" stroke-width=\"1.4\" fill=\"none\"/><path d=\"M198 77 L222 77\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"226\" y=\"42\" width=\"170\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"311\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">Mask R-CNN<\/text><text x=\"311\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">像素级分割<\/text><path d=\"M400 77 L424 77\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"428\" y=\"42\" width=\"168\" height=\"70\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"512\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">裂缝掩膜<\/text><text x=\"512\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">每条一条 · 可数可量<\/text><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：裂缝细长低对比 → 易漏或粘连<\/text><\/svg>"},{"name":"骨架化与线密度","role":"算法核心","do":"对裂缝掩膜做细化（骨架化），提炼裂缝中心线，量出每条裂缝的长度与走向，统计线密度。示范页屏 2 实时展示骨架提取与长度统计。","effect":"每条裂缝的中心线、长度、走向可算，线密度自动统计。","trap":"裂缝分叉 / 交叉处骨架易错，长度与走向量偏。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">骨架化：裂缝掩膜 → 中心线 → 长度 / 走向<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"70\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"99\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">裂缝掩膜<\/text><path d=\"M50 90 L140 60\" stroke=\"#b26a39\" stroke-width=\"4\" stroke-linecap=\"round\"/><path d=\"M178 68 L202 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">骨架化<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">细化出中心线<\/text><path d=\"M360 68 L384 68\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"200\" height=\"70\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"488\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">长度 + 走向<\/text><text x=\"488\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">线密度自动统计<\/text><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：裂缝分叉 / 交叉 → 骨架易错 → 长度走向量偏<\/text><\/svg>"},{"name":"摄影测量标定","role":"工程环节","do":"用标定板与无人机点云完成相机标定，把像素几何换算成真实方位与尺度。示范页屏 3 展示标定与像素到产状的换算。","effect":"像素距离变成真实厘米，为反算产状提供几何基准。","trap":"缺标定基准时像素≠真实产状，算出的走向与开度整体偏差。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">摄影测量标定：像素 → 真实方位与尺度<\/text><rect x=\"24\" y=\"42\" width=\"170\" height=\"70\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"109\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">标定板 + 点云<\/text><text x=\"109\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">几何基准<\/text><path d=\"M198 77 L222 77\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"226\" y=\"42\" width=\"150\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"301\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">相机标定<\/text><text x=\"301\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">内外参 + 尺度<\/text><path d=\"M380 77 L404 77\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"408\" y=\"42\" width=\"188\" height=\"70\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"502\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">真实产状<\/text><text x=\"502\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">走向 / 开度 / 密度<\/text><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：缺标定基准 → 像素≠产状 → 走向开度整体偏差<\/text><\/svg>"},{"name":"产状反算与统计","role":"算法核心","do":"把骨架走向换算成真实地质产状，统计裂缝走向分布、线密度与开度。示范页屏 3 实时展示产状玫瑰图与线密度。","effect":"每个露头的走向、线密度、开度自动出结果，取代人工逐条量。","trap":"走向分布对投影方向敏感，需按裂缝分组统计避免失真。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">产状反算：骨架走向 → 走向分布 + 线密度<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"70\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"99\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">骨架走向<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">每条裂缝<\/text><path d=\"M178 68 L202 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">产状换算<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">标定 + 方位<\/text><path d=\"M360 68 L384 68\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"200\" height=\"70\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"488\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">走向分布 + 线密度<\/text><text x=\"488\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">取代人工量<\/text><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：走向分布对投影方向敏感 → 需按组统计<\/text><\/svg>"},{"name":"实测验证与回写","role":"人工确认","do":"用罗盘实测记录（100—200 条）验证算法产状，校准走向误差（≤3°），修正样本回写训练集。示范页屏 3 展示验证与校准。","effect":"算法产状经实测校准，走向误差可控，掩膜样本越用越全。","trap":"只自动不实测验证，走向误差不被发现，建模用错参数。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">实测验证：算法产状 ←→ 罗盘实测校准<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">算法产状<\/text><text x=\"104\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">自动统计<\/text><path d=\"M188 68 L212 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"216\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"296\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">罗盘实测<\/text><text x=\"296\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">100—200 条验证集<\/text><path d=\"M380 68 L404 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"408\" y=\"42\" width=\"188\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"502\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">校准 + 回写<\/text><text x=\"502\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">误差 ≤3° · 样本回流<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：只自动不实测 → 走向误差不被发现 → 建模用错参数<\/text><\/svg>"}],"metrics":{"title":"怎么算「裂缝统计对了」","html":"<p>核心看 <b>走向误差<\/b>：算法反算产状与罗盘实测的走向偏差（越小越好），以及 <b>线密度 / 裂缝条数<\/b>是否与人工核对一致。<\/p><p>分割本身验收用 <b>实例分割 mAP<\/b>、<b>骨架长度一致性<\/b>；但必须<b>按裂缝分组分块验证<\/b>——走向分布对投影方向敏感，整体混算会把不同组裂缝的误差互相掩盖。<\/p><p style=\"margin-top:16px\"><svg viewBox='0 0 620 200' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='裂缝统计效果对比' style='width:100%;height:auto;display:block'><text x='14' y='20' font-size='10' fill='#4d565b' font-weight='600'>某裂缝型露头 · 人工测量 vs 智能流水线<\/text><rect x='14' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='159' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>走向误差<\/text><rect x='60' y='88' width='70' height='46' fill='#d9b78e'/><text x='95' y='116' text-anchor='middle' font-size='10' fill='#4d565b' font-weight='700'>10°<\/text><text x='95' y='130' text-anchor='middle' font-size='8' fill='#8a6b52'>人工测量<\/text><rect x='180' y='74' width='70' height='60' fill='#2f7d6b'/><text x='215' y='108' text-anchor='middle' font-size='10' fill='#fff' font-weight='700'>≤3°<\/text><text x='215' y='124' text-anchor='middle' font-size='8' fill='#b9d8cb'>智能流水线<\/text><text x='159' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>经实测校准后误差可控<\/text><rect x='316' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='461' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>单露头测量耗时<\/text><rect x='400' y='56' width='90' height='78' fill='#d9b78e'/><text x='445' y='92' text-anchor='middle' font-size='10' fill='#4d565b' font-weight='700'>半天<\/text><text x='445' y='108' text-anchor='middle' font-size='8' fill='#8a6b52'>人工测量<\/text><rect x='540' y='98' width='70' height='36' fill='#2f7d6b'/><text x='575' y='120' text-anchor='middle' font-size='10' fill='#fff' font-weight='700'>分钟级<\/text><text x='575' y='136' text-anchor='middle' font-size='8' fill='#b9d8cb'>智能流水线<\/text><text x='461' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>耗时降一个量级<\/text><text x='310' y='188' text-anchor='middle' font-size='8' fill='#9ba3a9'>验收 = 走向误差 ≤3° × 线密度一致 × 按裂缝分组验证 · 三项都要达标<\/text><\/svg><\/p>"},"fails":[{"name":"裂缝粘连","why":"裂缝细长且交叉，实例分割把多条裂缝误分成一条，条数与线密度统计偏少。"},{"name":"走向整体偏差","why":"缺几何标定基准，像素走向换算成真实产状时整体旋转/缩放，走向统计系统性错误。"},{"name":"小裂缝漏检","why":"开度小的裂缝只有几个像素、对比度低，分割模型漏检，统计结果偏少。"},{"name":"骨架分叉错位","why":"裂缝分叉或交叉处骨架化易错，长度与走向量偏，影响线密度统计。"}]}}};
  DEF.tabs.demo = {
    label: "可运行示范",
    intro: "用合成的露头裂缝照片演示实例分割、骨架化与产状反算。",
    mode: "page",
    mount: function (root, ctx) {
      handle = window.CaseDemoHost.create(root, { files: FILES, demo: CFG, meta: META }, ctx);
    },
    unmount: function () {
      if (handle) { try { handle.destroy(); } catch (e) { } handle = null; }
    }
  };
  window.Cases.register(DEF);
})();
